package com.example.securefile.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;
import org.springframework.validation.annotation.Validated;

import jakarta.validation.constraints.NotBlank;

/**
 * Konfiguration des Upload-Root-Verzeichnisses.
 * Das Verzeichnis sollte außerhalb des Classpath und mit restriktiven
 * Dateisystem-Rechten betrieben werden (siehe auch FIO00-J).
 */
@Component
@ConfigurationProperties(prefix = "app.file-storage")
@Validated
public class FileStorageProperties {

    /**
     * Absoluter oder relativer Pfad zum Upload-Verzeichnis.
     * Wird zur Laufzeit kanonisiert.
     */
    @NotBlank
    private String uploadDir = "uploads";

    public String getUploadDir() {
        return uploadDir;
    }

    public void setUploadDir(String uploadDir) {
        this.uploadDir = uploadDir;
    }
}
