"}, {"type": "CODE_BLOCK", "language": "java", "content": "// AllowedExtension.java
package com.example.securefile.domain;

import java.util.Arrays;
import java.util.Locale;
import java.util.Optional;

/**
 * Whitelist erlaubter Dateiendungen und der zugehörigen Content-Types.
 * Verhindert sowohl Path-Traversal über getarnte Namen als auch
 * das Ausliefern ausführbarer oder interpretierbarer Inhalte (CWE-434).
 */
public enum AllowedExtension {

    TXT("txt", "text/plain"),
    PDF("pdf", "application/pdf"),
    PNG("png", "image/png"),
    JPG("jpg", "image/jpeg"),
    JPEG("jpeg", "image/jpeg");

    private final String extension;
    private final String contentType;

    AllowedExtension(String extension, String contentType) {
        this.extension = extension;
        this.contentType = contentType;
    }

    public String getExtension() {
        return extension;
    }

    public String getContentType() {
        return contentType;
    }

    /**
     * Liefert die erlaubte Extension nur dann, wenn sie exakt in der Whitelist steht.
     */
    public static Optional<AllowedExtension> fromFileName(String fileName) {
        if (fileName == null || fileName.isBlank()) {
            return Optional.empty();
        }
        String normalized = fileName.trim().toLowerCase(Locale.ROOT);
        int lastDot = normalized.lastIndexOf('.');
        if (lastDot < 0 || lastDot == normalized.length() - 1) {
            return Optional.empty();
        }
        String ext = normalized.substring(lastDot + 1);
        return Arrays.stream(values())
                .filter(a -> a.extension.equals(ext))
                .findFirst();
    }
}
