package com.example.securefile.exception;

/**
 * Wird bei jeder Verletzung der Speicher-Sicherheitsregeln geworfen.
 * Die Message ist bewusst generisch, um keine internen Pfade zu leaken.
 */
public class FileStorageException extends RuntimeException {

    public FileStorageException(String message) {
        super(message);
    }

    public FileStorageException(String message, Throwable cause) {
        super(message, cause);
    }
}
