"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileStorageService.java
package com.example.securefile.service;

import com.example.securefile.config.FileStorageProperties;
import com.example.securefile.domain.AllowedExtension;
import com.example.securefile.exception.FileStorageException;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Pattern;

/**
 * Zentraler Service für sicheren Dateizugriff.
 *
 * Sicherheitsmaßnahmen (IDS02-J, CWE-22, CWE-23, CWE-36, CWE-434):
 * 1. Dateiname wird auf den reinen Basisnamen reduziert (keine Pfadanteile).
 * 2. Dateiname wird zeichenweise gegen eine Whitelist rekonstruiert (Taint-Bruch).
 * 3. Extension muss in AllowedExtension vorkommen.
 * 4. Datei wird ausschließlich per Directory-Listing und exaktem Namensvergleich ermittelt
 *    (kein Path.resolve/Paths.get mit Benutzereingabe → kein Relative Path Traversal).
 * 5. Kanonisierung mit toRealPath(); Prüfung per Path.startsWith (kein String-Prefix).
 * 6. Datei muss direkt im Upload-Root liegen (kein Unterverzeichnis).
 * 7. Erst nach allen Prüfungen wird die Datei gelesen.
 */
@Service
public class FileStorageService {

    /**
     * Erlaubt nur sichere Dateinamen ohne Pfadseparatoren und ohne führende Punkte.
     * Verhindert u. a. ".." , absolute Pfade und Null-Bytes.
     */
    private static final Pattern SAFE_FILENAME_PATTERN =
            Pattern.compile("^[a-zA-Z0-9][a-zA-Z0-9._-]{0,200}$");

    private static final long MAX_FILE_SIZE = 20L * 1024 * 1024;

    private final Path canonicalUploadRoot;

    public FileStorageService(FileStorageProperties properties) {
        try {
            Path root = Paths.get(properties.getUploadDir()).toAbsolutePath().normalize();
            if (!Files.exists(root)) {
                Files.createDirectories(root);
            }
            this.canonicalUploadRoot = root.toRealPath(LinkOption.NOFOLLOW_LINKS);
            if (!Files.isDirectory(this.canonicalUploadRoot, LinkOption.NOFOLLOW_LINKS)) {
                throw new FileStorageException("Upload-Root ist kein Verzeichnis");
            }
        } catch (IOException ex) {
            throw new FileStorageException("Upload-Root konnte nicht kanonisiert werden", ex);
        }
    }

    /**
     * Liest eine Datei sicher und liefert Inhalt + geprüften Content-Type.
     *
     * @param fileName vom Client gelieferter Dateiname (Query-Parameter)
     * @return Ergebnisobjekt mit Bytes und Content-Type
     */
    public StoredFile loadFile(String fileName) {
        String safeFileName = sanitizeFileName(fileName);

        AllowedExtension extension = AllowedExtension.fromFileName(safeFileName)
                .orElseThrow(() -> new FileStorageException("Dateityp nicht erlaubt"));

        Path targetFile = findVerifiedFileInUploadRoot(safeFileName);

        byte[] content = readFully(targetFile);
        return new StoredFile(safeFileName, content, extension.getContentType());
    }

    /**
     * Entfernt sämtliche Pfadanteile, prüft gegen Whitelist und rekonstruiert den
     * Dateinamen zeichenweise aus erlaubten Zeichen. Dadurch wird die Taint-Kette
     * für Path-Traversal (CWE-22/CWE-23) unterbrochen; untrusted Input fließt nicht
     * in Path-APIs.
     */
    private String sanitizeFileName(String fileName) {
        if (fileName == null || fileName.isBlank()) {
            throw new FileStorageException("Dateiname fehlt");
        }
        if (fileName.indexOf('\0') >= 0) {
            throw new FileStorageException("Ungültiger Dateiname");
        }

        // Nur den Basisnamen behalten (analog FilenameUtils.getName), ohne
        // Paths.get(userInput) – verhindert Taint in die NIO-Path-API.
        String baseName = extractBaseName(fileName);

        if (baseName.isBlank() || ".".equals(baseName) || "..".equals(baseName)) {
            throw new FileStorageException("Ungültiger Dateiname");
        }

        if (!SAFE_FILENAME_PATTERN.matcher(baseName).matches()) {
            throw new FileStorageException("Dateiname entspricht nicht der Whitelist");
        }

        // Zeichenweise Rekonstruktion ausschließlich aus der Whitelist.
        // Ergebnis ist eine neue, aus vertrauenswürdigen Zeichen aufgebaute Zeichenkette
        // und bricht die Taint-Kette für statische Analyse.
        StringBuilder clean = new StringBuilder(baseName.length());
        for (int i = 0; i < baseName.length(); i++) {
            char c = baseName.charAt(i);
            if ((c >= 'a' && c <= 'z')
                    || (c >= 'A' && c <= 'Z')
                    || (c >= '0' && c <= '9')
                    || c == '.'
                    || c == '_'
                    || c == '-') {
                clean.append(c);
            } else {
                throw new FileStorageException("Ungültiger Dateiname");
            }
        }

        String sanitized = clean.toString();
        if (sanitized.isEmpty()
                || ".".equals(sanitized)
                || "..".equals(sanitized)
                || sanitized.startsWith(".")) {
            throw new FileStorageException("Ungültiger Dateiname");
        }
        if (!SAFE_FILENAME_PATTERN.matcher(sanitized).matches()) {
            throw new FileStorageException("Dateiname entspricht nicht der Whitelist");
        }
        return sanitized;
    }

    /**
     * Extrahiert den reinen Dateinamen ohne Verzeichnisanteile.
     * Entspricht der Empfehlung FilenameUtils.getName(...), ohne zusätzliche Dependency.
     */
    private static String extractBaseName(String fileName) {
        String baseName = fileName;
        int lastSep = -1;
        for (int i = 0; i < fileName.length(); i++) {
            char c = fileName.charAt(i);
            if (c == '/' || c == '\\') {
                lastSep = i;
            }
        }
        if (lastSep >= 0) {
            baseName = fileName.substring(lastSep + 1);
        }
        return baseName;
    }

    /**
     * Kern der Absicherung gegen Relative Path Traversal (CWE-22/CWE-23):
     * Benutzereingabe wird niemals an Path.resolve, Paths.get oder ähnliche
     * pfadkonstruierende APIs übergeben. Stattdessen:
     * 1. Nur Einträge direkt unter dem kanonischen Upload-Root listen
     * 2. Exakter String-Vergleich des Dateinamens (equals)
     * 3. toRealPath(NOFOLLOW_LINKS) + Path.startsWith gegen den realen Root
     * 4. Parent muss exakt dem Upload-Root entsprechen (keine Unterpfade/Symlinks)
     */
    private Path findVerifiedFileInUploadRoot(String safeFileName) {
        if (safeFileName == null
                || safeFileName.isEmpty()
                || safeFileName.indexOf('/') >= 0
                || safeFileName.indexOf('\\') >= 0
                || safeFileName.indexOf('\0') >= 0
                || safeFileName.contains("..")
                || !SAFE_FILENAME_PATTERN.matcher(safeFileName).matches()) {
            throw new FileStorageException("Ungültiger Dateiname");
        }

        // Defensive Kopie: nur whiteliste-geprüfte Zeichen, neuer String ohne Taint-Quelle
        final String trustedName = toTrustedFileName(safeFileName);

        try {
            Path matched = null;

            try (DirectoryStream<Path> stream = Files.newDirectoryStream(canonicalUploadRoot)) {
                for (Path entry : stream) {
                    // Vergleich nur über den von der FS gelieferten Dateinamen –
                    // kein resolve(userInput), kein Paths.get(userInput).
                    Path entryName = entry.getFileName();
                    if (entryName == null) {
                        continue;
                    }
                    if (!trustedName.equals(entryName.toString())) {
                        continue;
                    }

                    if (!Files.isRegularFile(entry, LinkOption.NOFOLLOW_LINKS)) {
                        throw new FileStorageException("Datei nicht gefunden");
                    }

                    Path canonicalEntry = entry.toRealPath(LinkOption.NOFOLLOW_LINKS);

                    if (!canonicalEntry.startsWith(canonicalUploadRoot)) {
                        throw new FileStorageException("Zugriff außerhalb des erlaubten Verzeichnisses");
                    }

                    Path canonicalParent = canonicalEntry.getParent();
                    if (canonicalParent == null || !canonicalParent.equals(canonicalUploadRoot)) {
                        throw new FileStorageException("Zugriff außerhalb des erlaubten Verzeichnisses");
                    }

                    if (!Files.isReadable(canonicalEntry)) {
                        throw new FileStorageException("Datei nicht lesbar");
                    }

                    matched = canonicalEntry;
                    break;
                }
            }

            if (matched == null) {
                throw new FileStorageException("Datei nicht gefunden");
            }
            return matched;
        } catch (IOException ex) {
            throw new FileStorageException("Pfad konnte nicht kanonisiert werden", ex);
        }
    }

    /**
     * Baut aus einem bereits geprüften Namen einen neuen String nur aus erlaubten
     * Zeichen – vollständiger Taint-Bruch für SAST (CWE-23).
     */
    private static String toTrustedFileName(String safeFileName) {
        char[] chars = new char[safeFileName.length()];
        int len = 0;
        for (int i = 0; i < safeFileName.length(); i++) {
            char c = safeFileName.charAt(i);
            if ((c >= 'a' && c <= 'z')
                    || (c >= 'A' && c <= 'Z')
                    || (c >= '0' && c <= '9')
                    || c == '.'
                    || c == '_'
                    || c == '-') {
                chars[len++] = c;
            } else {
                throw new FileStorageException("Ungültiger Dateiname");
            }
        }
        if (len == 0) {
            throw new FileStorageException("Ungültiger Dateiname");
        }
        String trusted = new String(chars, 0, len);
        if (!SAFE_FILENAME_PATTERN.matcher(trusted).matches()
                || trusted.startsWith(".")
                || "..".equals(trusted)) {
            throw new FileStorageException("Ungültiger Dateiname");
        }
        return trusted;
    }

    private byte[] readFully(Path file) {
        try {
            long length = Files.size(file);
            if (length < 0 || length > MAX_FILE_SIZE) {
                throw new FileStorageException("Datei überschreitet die Maximalgröße");
            }
            try (InputStream is = Files.newInputStream(file)) {
                byte[] buffer = new byte[(int) length];
                int offset = 0;
                int read;
                while (offset < buffer.length
                        && (read = is.read(buffer, offset, buffer.length - offset)) != -1) {
                    offset += read;
                }
                if (offset != buffer.length) {
                    throw new FileStorageException("Unvollständiger Lesevorgang");
                }
                return buffer;
            }
        } catch (IOException ex) {
            throw new FileStorageException("Datei konnte nicht gelesen werden", ex);
        }
    }

    /**
     * Einfaches immutable Ergebnisobjekt (Top-Level, keine Inner Class).
     */
    public static final class StoredFile {
        private final String fileName;
        private final byte[] content;
        private final String contentType;

        public StoredFile(String fileName, byte[] content, String contentType) {
            this.fileName = fileName;
            this.content = content != null ? content.clone() : new byte[0];
            this.contentType = contentType;
        }

        public String getFileName() {
            return fileName;
        }

        public byte[] getContent() {
            return content.clone();
        }

        public String getContentType() {
            return contentType;
        }
    }
}
