"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileDownloadController.java
package com.example.securefile.web;

import com.example.securefile.service.FileStorageService;
import com.example.securefile.service.FileStorageService.StoredFile;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt zum sicheren Herunterladen einer Datei.
 * Der Controller enthält keine eigene Pfadlogik – alles läuft über den Service.
 */
@RestController
@RequestMapping("/api/v1/files")
public class FileDownloadController {

    private final FileStorageService fileStorageService;

    public FileDownloadController(FileStorageService fileStorageService) {
        this.fileStorageService = fileStorageService;
    }

    /**
     * GET /api/v1/files/download?fileName=beispiel.pdf
     *
     * fileName wird ausschließlich als Query-Parameter entgegengenommen und
     * sofort an den Service übergeben, der kanonisiert und validiert.
     */
    @GetMapping("/download")
    public ResponseEntity<byte[]> downloadFile(
            @RequestParam("fileName") String fileName) {

        StoredFile storedFile = fileStorageService.loadFile(fileName);

        // Content-Type kommt ausschließlich aus der serverseitigen Whitelist (CWE-434)
        MediaType mediaType = MediaType.parseMediaType(storedFile.getContentType());

        return ResponseEntity.ok()
                .contentType(mediaType)
                .header(HttpHeaders.CONTENT_DISPOSITION,
                        "attachment; filename=\"" + storedFile.getFileName() + "\"")
                .header(HttpHeaders.X_CONTENT_TYPE_OPTIONS, "nosniff")
                .contentLength(storedFile.getContent().length)
                .body(storedFile.getContent());
    }
}
