"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.securefile.web;

import com.example.securefile.exception.FileStorageException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

/**
 * Mappt Sicherheits- und Speicherfehler auf generische HTTP-Antworten.
 * Es werden keine internen Pfade oder Stacktraces an den Client zurückgegeben.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(FileStorageException.class)
    public ResponseEntity<Map<String, String>> handleFileStorageException(
            FileStorageException ex) {

        // Bewusst generische Meldung – keine Unterscheidung, die einem Angreifer hilft
        String clientMessage = "Anfrage abgelehnt oder Datei nicht verfügbar";
        HttpStatus status = HttpStatus.BAD_REQUEST;

        String msg = ex.getMessage() != null ? ex.getMessage().toLowerCase() : "";
        if (msg.contains("nicht gefunden") || msg.contains("nicht lesbar")) {
            status = HttpStatus.NOT_FOUND;
        } else if (msg.contains("außerhalb") || msg.contains("nicht erlaubt")) {
            status = HttpStatus.FORBIDDEN;
        }

        return ResponseEntity.status(status)
                .body(Map.of("error", clientMessage));
    }
}
