package com.example.securefiles;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.MalformedURLException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Pattern;

/**
 * Zentraler Service für sicheren Dateizugriff.
 * Alle Pfadprüfungen und die Durchsetzung der Basisverzeichnis-
 * Grenze (data/docs) erfolgen ausschließlich hier (Defense in Depth,
 * Deny-by-Default, CWE-22/CWE-23/CWE-284/CWE-552).
 */
@Service
public class FileStorageService {

    private static final Logger log = LoggerFactory.getLogger(FileStorageService.class);

    /**
     * Fest verdrahtetes, relatives Basisverzeichnis.
     * Wird beim Start absolut und normalisiert aufgelöst.
     */
    private static final String BASE_DIRECTORY = "data/docs";

    /**
     * Erlaubte Dateinamen: nur alphanumerisch, Punkt, Unterstrich, Bindestrich.
     * Keine Pfadtrenner, keine Traversal-Sequenzen, kein führender Punkt.
     */
    private static final Pattern SAFE_FILENAME =
            Pattern.compile("^[a-zA-Z0-9][a-zA-Z0-9._-]{0,254}$");

    private final Path baseDir;

    public FileStorageService() throws IOException {
        this.baseDir = Paths.get(BASE_DIRECTORY)
                .toAbsolutePath()
                .normalize();

        if (!Files.exists(this.baseDir)) {
            Files.createDirectories(this.baseDir);
            log.info("Basisverzeichnis angelegt: {}", this.baseDir);
        }

        if (!Files.isDirectory(this.baseDir)) {
            throw new IllegalStateException(
                    "Konfiguriertes Basisverzeichnis ist kein Verzeichnis: " + this.baseDir);
        }

        log.info("FileStorageService initialisiert. Erlaubtes Wurzelverzeichnis: {}", this.baseDir);
    }

    /**
     * Liefert die angeforderte Datei als Resource, sofern sie
     * vollständig innerhalb von data/docs liegt.
     *
     * @param userProvidedPath vom Client gelieferter Dateiname (kein Pfad)
     * @return Resource der Datei
     * @throws InvalidFilePathException bei Path-Traversal oder ungültiger Eingabe
     * @throws SecureFileNotFoundException wenn Datei nicht existiert / keine reguläre Datei
     */
    public Resource loadFileAsResource(String userProvidedPath) {
        // Eingabe wird ausschließlich auf einen whitelisted Dateinamen reduziert;
        // danach fließt kein benutzergesteuerter Pfad mehr in Dateisystem-APIs.
        final String safeFileName = sanitizeToSafeFileName(userProvidedPath);
        final Path resolvedPath = resolveInsideBaseDir(safeFileName);

        try {
            Resource resource = new UrlResource(resolvedPath.toUri());
            if (!resource.exists() || !resource.isReadable()) {
                log.warn("Datei nicht lesbar oder nicht vorhanden (nach Validierung): {}",
                        sanitizeForLog(safeFileName));
                throw new SecureFileNotFoundException("Datei nicht gefunden.");
            }
            return resource;
        } catch (MalformedURLException ex) {
            log.error("Ungültige URL beim Erzeugen der Resource für Eingabe: {}",
                    sanitizeForLog(safeFileName), ex);
            throw new InvalidFilePathException("Ungültiger Dateipfad.", ex);
        }
    }

    /**
     * Reduziert benutzergesteuerte Eingabe auf einen einzelnen, whitelisted Dateinamen.
     * Keine Verzeichnisanteile, keine Traversal-Sequenzen, keine Pfadtrenner.
     * Entschärft CWE-22/CWE-23 (Relative/Absolute Path Traversal).
     */
    private String sanitizeToSafeFileName(String userProvidedPath) {
        if (userProvidedPath == null || userProvidedPath.isBlank()) {
            log.warn("Access-Control-Verstoß: leerer oder null Dateiparameter");
            throw new InvalidFilePathException("Dateiparameter darf nicht leer sein.");
        }

        // Null-Byte-Injection abwehren (klassische Bypass-Technik)
        if (userProvidedPath.indexOf('\0') >= 0) {
            log.warn("Access-Control-Verstoß: Null-Byte in Dateiparameter erkannt");
            throw new InvalidFilePathException("Ungültiger Dateiparameter.");
        }

        // Alle Pfadtrenner und Traversal-Metazeichen vorab ablehnen (keine Normalisierung als Bypass)
        if (userProvidedPath.indexOf('/') >= 0
                || userProvidedPath.indexOf('\\') >= 0
                || userProvidedPath.contains("..")
                || userProvidedPath.indexOf(':') >= 0) {
            log.warn("Access-Control-Verstoß: Pfadtrenner/Traversal in Eingabe: {}",
                    sanitizeForLog(userProvidedPath));
            throw new InvalidFilePathException("Pfadangaben sind nicht erlaubt.");
        }

        // Nur den reinen Dateinamen behalten (analog zu FilenameUtils.getName)
        // – ohne Paths.get() auf untrusted Input, um Taint-Propagation zu vermeiden.
        String fileName = extractFileNameOnly(userProvidedPath);

        if (fileName.isEmpty() || ".".equals(fileName) || "..".equals(fileName)) {
            log.warn("Access-Control-Verstoß: kein gültiger Dateiname ermittelbar");
            throw new InvalidFilePathException("Ungültiger Dateiparameter.");
        }

        // Identitätsprüfung: Eingabe muss exakt dem Dateinamen entsprechen
        if (!fileName.equals(userProvidedPath)) {
            log.warn("Access-Control-Verstoß: Eingabe enthält Pfadanteile: {}",
                    sanitizeForLog(userProvidedPath));
            throw new InvalidFilePathException("Pfadangaben sind nicht erlaubt.");
        }

        // Whitelist: nur sichere Dateinamen-Zeichen zulassen
        if (!SAFE_FILENAME.matcher(fileName).matches()) {
            log.warn("Access-Control-Verstoß: Dateiname entspricht nicht der Whitelist: {}",
                    sanitizeForLog(userProvidedPath));
            throw new InvalidFilePathException("Ungültiger Dateiname.");
        }

        return fileName;
    }

    /**
     * Extrahiert den letzten Pfadbestandteil rein stringbasiert,
     * ohne NIO-Path-APIs auf untrusted Input anzuwenden.
     */
    private static String extractFileNameOnly(String input) {
        String name = input;
        int lastSlash = Math.max(name.lastIndexOf('/'), name.lastIndexOf('\\'));
        if (lastSlash >= 0) {
            name = name.substring(lastSlash + 1);
        }
        // Windows-Laufwerksbuchstabe / UNC-Reste entfernen
        int colon = name.lastIndexOf(':');
        if (colon >= 0) {
            name = name.substring(colon + 1);
        }
        return name;
    }

    /**
     * Löst den bereits validierten Dateinamen ausschließlich innerhalb von baseDir auf.
     * @param safeFileName bereits durch sanitizeToSafeFileName geprüfter Name (kein User-Pfad)
     */
    private Path resolveInsideBaseDir(String safeFileName) {
        // safeFileName ist whitelist-geprüft und enthält keine Pfadtrenner
        Path resolved = baseDir.resolve(safeFileName).normalize();

        // Entscheidende Grenze: nach Normalisierung muss der Pfad noch unter baseDir liegen
        if (!resolved.startsWith(baseDir)) {
            log.warn("Access-Control-Verstoß (Path Traversal): Dateiname='{}', aufgelöst='{}'",
                    sanitizeForLog(safeFileName), resolved);
            throw new InvalidFilePathException(
                    "Zugriff verweigert: Pfad liegt außerhalb des erlaubten Verzeichnisses.");
        }

        // Nur reguläre Dateien – keine Verzeichnisse, keine Named Pipes etc.
        if (!Files.exists(resolved) || !Files.isRegularFile(resolved)) {
            log.info("Datei nicht gefunden oder keine reguläre Datei: {}",
                    sanitizeForLog(safeFileName));
            throw new SecureFileNotFoundException("Datei nicht gefunden.");
        }

        // Symbolische Links, die aus dem Basisverzeichnis herausführen, ablehnen
        try {
            Path realBase = baseDir.toRealPath();
            Path realResolved = resolved.toRealPath();
            if (!realResolved.startsWith(realBase)) {
                log.warn("Access-Control-Verstoß: Symlink/RealPath führt aus Basisverzeichnis: {}",
                        realResolved);
                throw new InvalidFilePathException(
                        "Zugriff verweigert: Pfad liegt außerhalb des erlaubten Verzeichnisses.");
            }
            return realResolved;
        } catch (IOException ex) {
            log.warn("RealPath-Prüfung fehlgeschlagen für: {}", sanitizeForLog(safeFileName), ex);
            throw new SecureFileNotFoundException("Datei nicht gefunden.");
        }
    }

    /**
     * Verhindert, dass potenziell bösartige Eingaben ungefiltert in Logs landen
     * (Log-Injection / übermäßig lange Strings).
     */
    private String sanitizeForLog(String input) {
        if (input == null) {
            return "null";
        }
        String cleaned = input.replaceAll("[\\r\\n\\t]", "_");
        return cleaned.length() > 128 ? cleaned.substring(0, 128) + "..." : cleaned;
    }

    /**
     * Liefert einen sicheren Dateinamen für den Content-Disposition-Header
     * (nur der letzte Pfadbestandteil, ohne Directory-Anteile).
     */
    public String getSafeDownloadFileName(String userProvidedPath) {
        if (userProvidedPath == null || userProvidedPath.isBlank()) {
            return "download";
        }
        // Kein Paths.get() auf untrusted Input – stringbasierte Extraktion
        String name = extractFileNameOnly(userProvidedPath);
        // Absicherung gegen Header-Injection und unsichere Zeichen
        name = name.replaceAll("[^a-zA-Z0-9._-]", "_");
        if (name.isEmpty() || ".".equals(name) || "..".equals(name)) {
            return "download";
        }
        return name.length() > 255 ? name.substring(0, 255) : name;
    }
}
