"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileDownloadController.java
package com.example.securefiles;

import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt für den sicheren Download von Dateien
 * ausschließlich aus dem Verzeichnis data/docs.
 *
 * Access Control wird serverseitig im FileStorageService durchgesetzt
 * (nicht im Frontend, nicht nur über „versteckte“ URLs) – siehe A01:2025.
 */
@RestController
@RequestMapping("/api/v1/files")
public class FileDownloadController {

    private final FileStorageService fileStorageService;

    public FileDownloadController(FileStorageService fileStorageService) {
        this.fileStorageService = fileStorageService;
    }

    /**
     * GET /api/v1/files/download?file=beispiel.pdf
     *
     * @param file relativer Dateiname oder relativer Pfad unterhalb von data/docs
     * @return Datei als Download-Resource
     */
    @GetMapping("/download")
    public ResponseEntity<Resource> downloadFile(
            @RequestParam("file") String file) {

        Resource resource = fileStorageService.loadFileAsResource(file);
        String safeFileName = fileStorageService.getSafeDownloadFileName(file);

        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_OCTET_STREAM)
                .header(HttpHeaders.CONTENT_DISPOSITION,
                        "attachment; filename=\"" + safeFileName + "\"")
                .header(HttpHeaders.X_CONTENT_TYPE_OPTIONS, "nosniff")
                .body(resource);
    }
}
