"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.securefiles;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Zentraler Exception-Handler.
 * Liefert bewusst generische Meldungen ohne interne Pfade,
 * Stacktraces oder Systemdetails (CWE-200, CWE-209, CWE-497).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(InvalidFilePathException.class)
    public ResponseEntity<Map<String, Object>> handleInvalidPath(InvalidFilePathException ex) {
        log.debug("InvalidFilePathException: {}", ex.getMessage());
        return buildBody(HttpStatus.BAD_REQUEST, "Ungültige Dateianfrage.");
    }

    @ExceptionHandler(SecureFileNotFoundException.class)
    public ResponseEntity<Map<String, Object>> handleNotFound(SecureFileNotFoundException ex) {
        log.debug("SecureFileNotFoundException: {}", ex.getMessage());
        return buildBody(HttpStatus.NOT_FOUND, "Datei nicht gefunden.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, Object>> handleGeneric(Exception ex) {
        log.error("Unerwarteter Fehler im File-Download", ex);
        return buildBody(HttpStatus.INTERNAL_SERVER_ERROR, "Interner Serverfehler.");
    }

    private ResponseEntity<Map<String, Object>> buildBody(HttpStatus status, String message) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", status.value());
        body.put("error", status.getReasonPhrase());
        body.put("message", message);
        return ResponseEntity.status(status).body(body);
    }
}
