"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CountValidator.java
package com.example.pingtool.validation;

import org.springframework.stereotype.Component;

/**
 * Strikte Validierung des count-Parameters gegen Integer-Overflow (CWE-190)
 * und Ping-Flooding (CWE-400). Erlaubt nur einen sehr kleinen, positiven Bereich.
 */
@Component
public class CountValidator {

    public static final int MIN_COUNT = 1;
    public static final int MAX_COUNT = 5; // bewusst niedrig gegen Flooding

    public int validate(String rawCount) {
        if (rawCount == null || rawCount.isBlank()) {
            return MIN_COUNT; // sicherer Default
        }

        final int count;
        try {
            count = Integer.parseInt(rawCount.trim());
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Count must be a valid integer");
        }

        // Explizite Range-Prüfung (verhindert Overflow-Folgen und zu große Last)
        if (count < MIN_COUNT || count > MAX_COUNT) {
            throw new IllegalArgumentException(
                    "Count must be between " + MIN_COUNT + " and " + MAX_COUNT);
        }

        return count;
    }
}
