"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitService.java
package com.example.pingtool.security;

import com.example.pingtool.exception.RateLimitExceededException;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Einfaches In-Memory-Rate-Limiting pro Client-IP (Token-Bucket-ähnlich).
 * Schützt vor Missbrauch und DoS (CWE-400). Für Produktion durch Bucket4j/Redis ersetzen.
 */
@Service
public class RateLimitService {

    private static final int MAX_REQUESTS_PER_WINDOW = 10;
    private static final long WINDOW_SECONDS = 60;

    private static final class Window {
        final AtomicInteger counter = new AtomicInteger(0);
        volatile long windowStartEpochSec;
    }

    private final Map<String, Window> buckets = new ConcurrentHashMap<>();

    public void checkAndConsume(String clientIp) {
        if (clientIp == null || clientIp.isBlank()) {
            clientIp = "unknown";
        }

        long now = Instant.now().getEpochSecond();
        Window window = buckets.computeIfAbsent(clientIp, k -> {
            Window w = new Window();
            w.windowStartEpochSec = now;
            return w;
        });

        synchronized (window) {
            if (now - window.windowStartEpochSec >= WINDOW_SECONDS) {
                window.windowStartEpochSec = now;
                window.counter.set(0);
            }

            if (window.counter.incrementAndGet() > MAX_REQUESTS_PER_WINDOW) {
                throw new RateLimitExceededException(
                        "Rate limit exceeded. Try again later.");
            }
        }
    }
}
