"}, {"type": "CODE_BLOCK", "language": "java", "content": "// PingService.java
package com.example.pingtool.service;

import com.example.pingtool.exception.PingExecutionException;
import com.example.pingtool.validation.CountValidator;
import com.example.pingtool.validation.TargetValidator;
import org.springframework.stereotype.Service;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

/**
 * Sichere Ping-Ausführung gemäß CERT IDS07-J / CWE-78-Mitigation.
 * - Kein Runtime.exec(String) / keine Shell
 * - ProcessBuilder ausschließlich mit Argumentliste (keine Metazeichen-Interpretation)
 * - Feste, absolute Binary-Pfade und feste Flags (keine User-Kontrolle)
 * - Zielhost zusätzlich per Whitelist + InetAddress abgesichert (Defense in Depth)
 * - Prozess-Timeout gegen Hänger und Ressourcenerschöpfung (CWE-400)
 */
@Service
public class PingService {

    private static final long PROCESS_TIMEOUT_SECONDS = 15;
    private static final int MIN_COUNT = 1;
    private static final int MAX_COUNT = 10;

    /**
     * Erlaubt nur Hostnamen (RFC 1123-ähnlich), IPv4 und IPv6 (inkl. optionaler Klammern).
     * Keine Shell-Metazeichen, Pfadtrenner, Leerzeichen oder Steuerzeichen.
     */
    private static final Pattern SAFE_TARGET = Pattern.compile(
            "^(?:"
                    + "(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)*"
                    + "[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
                    + "|(?:\\d{1,3}\\.){3}\\d{1,3}"
                    + "|\\[(?:[0-9a-fA-F:]+)\\]"
                    + "|(?:[0-9a-fA-F]{0,4}:){2,7}[0-9a-fA-F]{0,4}"
                    + ")$"
    );

    private final TargetValidator targetValidator;
    private final CountValidator countValidator;

    public PingService(TargetValidator targetValidator, CountValidator countValidator) {
        this.targetValidator = targetValidator;
        this.countValidator = countValidator;
    }

    public String ping(String rawTarget, String rawCount) {
        final String target;
        final int count;
        try {
            target = enforceSafeTarget(targetValidator.validateAndSanitize(rawTarget));
            count = enforceSafeCount(countValidator.validate(rawCount));
        } catch (IllegalArgumentException ex) {
            throw ex;
        }

        List<String> command = buildSecurePingCommand(target, count);

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true);
        processBuilder.environment().clear();
        // Kein shell-ähnliches Verhalten; Arbeitsverzeichnis fest und unkritisch
        processBuilder.directory(Paths.get(System.getProperty("java.io.tmpdir")).toFile());

        Process process = null;
        try {
            process = processBuilder.start();

            boolean finished = process.waitFor(PROCESS_TIMEOUT_SECONDS, TimeUnit.SECONDS);
            if (!finished) {
                process.destroyForcibly();
                throw new PingExecutionException("Ping timed out");
            }

            StringBuilder output = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append('\n');
                }
            }

            return output.toString().isEmpty()
                    ? "No output from ping (exit code " + process.exitValue() + ")"
                    : output.toString();

        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
            if (process != null) {
                process.destroyForcibly();
            }
            throw new PingExecutionException("Ping interrupted", ex);
        } catch (PingExecutionException ex) {
            throw ex;
        } catch (Exception ex) {
            if (process != null) {
                process.destroyForcibly();
            }
            throw new PingExecutionException("Failed to execute ping", ex);
        }
    }

    /**
     * Defense-in-Depth: Whitelist + DNS/IP-Auflösung, bevor der Wert jemals
     * als einzelnes Process-Argument verwendet wird.
     */
    private static String enforceSafeTarget(String candidate) {
        if (candidate == null || candidate.isEmpty() || candidate.length() > 253) {
            throw new IllegalArgumentException("Invalid target");
        }
        if (!SAFE_TARGET.matcher(candidate).matches()) {
            throw new IllegalArgumentException("Invalid target format");
        }
        // Ablehnung von speziellen/lokalen Missbrauchspfaden
        if (candidate.contains("..") || candidate.indexOf('/') >= 0 || candidate.indexOf('\\') >= 0) {
            throw new IllegalArgumentException("Invalid target characters");
        }
        try {
            String host = candidate;
            if (host.startsWith("[") && host.endsWith("]")) {
                host = host.substring(1, host.length() - 1);
            }
            // Wirft UnknownHostException bei unauflösbaren/ungültigen Namen
            InetAddress.getByName(host);
        } catch (Exception ex) {
            throw new IllegalArgumentException("Target is not a resolvable host or IP", ex);
        }
        return candidate;
    }

    private static int enforceSafeCount(int count) {
        if (count < MIN_COUNT || count > MAX_COUNT) {
            throw new IllegalArgumentException(
                    "Count must be between " + MIN_COUNT + " and " + MAX_COUNT);
        }
        return count;
    }

    /**
     * Baut das Kommando ausschließlich aus Konstanten + streng geprüften Werten.
     * Niemals User-Input in Flags, Binary-Namen oder zusammengesetzten Strings.
     */
    private List<String> buildSecurePingCommand(String sanitizedTarget, int safeCount) {
        List<String> cmd = new ArrayList<>(8);
        String os = System.getProperty("os.name", "").toLowerCase();

        if (os.contains("win")) {
            cmd.add(resolvePingBinary(
                    Paths.get(System.getenv("SystemRoot") != null
                            ? System.getenv("SystemRoot")
                            : "C:\\Windows", "System32", "ping.exe"),
                    "ping.exe"));
            cmd.add("-n");
            cmd.add(Integer.toString(safeCount));
        } else {
            cmd.add(resolvePingBinary(Paths.get("/bin/ping"), "/bin/ping"));
            cmd.add("-c");
            cmd.add(Integer.toString(safeCount));
            cmd.add("-W");
            cmd.add("2");
        }

        // Einziges externes Datum: bereits whitelist-validiertes Einzelargument
        cmd.add(sanitizedTarget);
        return cmd;
    }

    private static String resolvePingBinary(Path preferred, String fallbackName) {
        if (preferred != null
                && Files.isRegularFile(preferred)
                && Files.isExecutable(preferred)) {
            return preferred.toAbsolutePath().toString();
        }
        // Fallback nur auf den festen Programmnamen ohne user-kontrollierten Pfad;
        // ProcessBuilder sucht dann in PATH – weiterhin ohne Shell.
        if (fallbackName == null || fallbackName.isEmpty()
                || fallbackName.indexOf('/') >= 0
                || fallbackName.indexOf('\\') >= 0) {
            throw new PingExecutionException("Ping binary not available");
        }
        return fallbackName;
    }
}
