package com.example.pingtool.web;

import com.example.pingtool.exception.InvalidInputException;
import com.example.pingtool.security.RateLimitService;
import com.example.pingtool.service.PingService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt GET /tools/ping?target=...&count=...
 * Liefert das Ping-Ergebnis als text/plain.
 */
@RestController
@RequestMapping("/tools")
public class PingController {

    private final PingService pingService;
    private final RateLimitService rateLimitService;

    public PingController(PingService pingService, RateLimitService rateLimitService) {
        this.pingService = pingService;
        this.rateLimitService = rateLimitService;
    }

    @GetMapping(value = "/ping", produces = MediaType.TEXT_PLAIN_VALUE)
    public ResponseEntity<String> ping(
            @RequestParam("target") String target,
            @RequestParam(value = "count", required = false) String count,
            HttpServletRequest request) {

        String clientIp = resolveClientIp(request);
        rateLimitService.checkAndConsume(clientIp);

        try {
            String result = pingService.ping(target, count);
            return ResponseEntity.ok(result);
        } catch (IllegalArgumentException ex) {
            throw new InvalidInputException(ex.getMessage());
        }
    }

    /**
     * Ermittelt die Client-IP unter Berücksichtigung gängiger Proxy-Header.
     * Nur das erste Element von X-Forwarded-For wird verwendet.
     */
    private String resolveClientIp(HttpServletRequest request) {
        String xff = request.getHeader("X-Forwarded-For");
        if (xff != null && !xff.isBlank()) {
            return xff.split(",")[0].trim();
        }
        String realIp = request.getHeader("X-Real-IP");
        if (realIp != null && !realIp.isBlank()) {
            return realIp.trim();
        }
        return request.getRemoteAddr();
    }
}
