## 3. Request-DTO mit Validierung

Das DTO erzwingt Allowlist-Validierung (Länge, erlaubte Zeichen) mittels Bean Validation. Das verhindert frühzeitig bösartige Payloads für XSS und Injection.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CreateGuestbookEntryRequest.java
package com.example.guestbook.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

public class CreateGuestbookEntryRequest {

    @NotBlank(message = "Name darf nicht leer sein")
    @Size(min = 1, max = 50, message = "Name muss zwischen 1 und 50 Zeichen lang sein")
    @Pattern(
        regexp = "^[a-zA-Z0-9\\s\\-äöüÄÖÜß]+$",
        message = "Name enthält ungültige Zeichen (nur Buchstaben, Zahlen, Leerzeichen und Bindestriche erlaubt)"
    )
    private String name;

    @NotBlank(message = "Text darf nicht leer sein")
    @Size(min = 1, max = 1000, message = "Text muss zwischen 1 und 1000 Zeichen lang sein")
    @Pattern(
        regexp = "^[a-zA-Z0-9\\s\\-.,!?;:'\"()äöüÄÖÜß\\n\\r]+$",
        message = "Text enthält ungültige Zeichen"
    )
    private String text;

    public CreateGuestbookEntryRequest() {
    }

    public CreateGuestbookEntryRequest(String name, String text) {
        this.name = name;
        this.text = text;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getText() {
        return text;
    }

    public void setText(String text) {
        this.text = text;
    }
}
