## 4. Service-Schicht

Der Service orchestriert Validierung, zusätzliche Sanitization (Entfernung potenziell gefährlicher Reste), Persistenz und Logging. Parametrisiertes Logging verhindert Log-Injection. Es wird bewusst kein HTML in der Speicherung erlaubt; die Anzeige escaped später.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GuestbookService.java
package com.example.guestbook.service;

import com.example.guestbook.dto.CreateGuestbookEntryRequest;
import com.example.guestbook.model.GuestbookEntry;
import com.example.guestbook.repository.GuestbookEntryRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Objects;

@Service
public class GuestbookService {

    private static final Logger log = LoggerFactory.getLogger(GuestbookService.class);

    private final GuestbookEntryRepository repository;

    public GuestbookService(GuestbookEntryRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public GuestbookEntry createEntry(CreateGuestbookEntryRequest request, String authenticatedUsername) {
        Objects.requireNonNull(request, "Request darf nicht null sein");
        Objects.requireNonNull(authenticatedUsername, "Username darf nicht null sein");

        // Zusätzliche Sanitization: Steuerzeichen und überflüssige Whitespaces entfernen
        String sanitizedName = sanitize(request.getName());
        String sanitizedText = sanitize(request.getText());

        GuestbookEntry entry = new GuestbookEntry(sanitizedName, sanitizedText);
        GuestbookEntry saved = repository.save(entry);

        // Parametrisiertes Logging (verhindert Log-Injection / CWE-117)
        log.info("Neuer Gästebuch-Eintrag erstellt von Benutzer '{}' mit ID {}", authenticatedUsername, saved.getId());

        return saved;
    }

    @Transactional(readOnly = true)
    public List<GuestbookEntry> findAllEntries() {
        log.debug("Abruf aller Gästebuch-Einträge");
        return repository.findAllByOrderByCreatedAtDesc();
    }

    private String sanitize(String input) {
        if (input == null) {
            return "";
        }
        // Entfernt Steuerzeichen außer gängigen Whitespace-Zeichen; trimmt
        String cleaned = input
            .replaceAll("[\\p{Cntrl}&&[^\r\n\t]]", "")
            .trim()
            .replaceAll("\\s{2,}", " ");
        // Harte Längenbegrenzung als Defense-in-Depth
        if (cleaned.length() > 1000) {
            cleaned = cleaned.substring(0, 1000);
        }
        return cleaned;
    }
}
", "fileName": "Component_3", "vulnerbility": null}, {"type": "TEXT", "text": "

## 5. Controller

Der Controller stellt den POST-Endpunkt (JSON-Body mit Validierung) und den GET-Endpunkt (HTML via Thymeleaf) bereit. `@Valid` greift die Bean-Validation ab. Thymeleaf mit `th:text` escaped automatisch (XSS-Schutz). Zugriff nur für authentifizierte Benutzer.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GuestbookController.java
package com.example.guestbook.web;

import com.example.guestbook.dto.CreateGuestbookEntryRequest;
import com.example.guestbook.model.GuestbookEntry;
import com.example.guestbook.service.GuestbookService;
import jakarta.validation.Valid;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.ResponseBody;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

import java.util.List;
import java.util.Map;

@Controller
public class GuestbookController {

    private static final Logger log = LoggerFactory.getLogger(GuestbookController.class);

    private final GuestbookService guestbookService;

    public GuestbookController(GuestbookService guestbookService) {
        this.guestbookService = guestbookService;
    }

    /**
     * GET: Liefert eine HTML-Seite mit allen Einträgen.
     * Thymeleaf escaped Name und Text automatisch über th:text (CWE-79-Schutz).
     * Die Werte werden "wie empfangen" (nach Validierung/Sanitization) angezeigt, jedoch sicher encoded.
     */
    @GetMapping(value = "/guestbook", produces = MediaType.TEXT_HTML_VALUE)
    public String showGuestbook(Model model, @AuthenticationPrincipal UserDetails user) {
        List<GuestbookEntry> entries = guestbookService.findAllEntries();
        model.addAttribute("entries", entries);
        model.addAttribute("username", user != null ? user.getUsername() : "anonymous");
        model.addAttribute("createRequest", new CreateGuestbookEntryRequest());
        log.debug("Gästebuch-Seite für Benutzer '{}' gerendert, {} Einträge", 
                  user != null ? user.getUsername() : "anonymous", entries.size());
        return "guestbook";
    }

    /**
     * POST (Form-Submit): Nimmt name und text entgegen, validiert streng und speichert.
     */
    @PostMapping(value = "/guestbook", consumes = MediaType.APPLICATION_FORM_URLENCODED_VALUE)
    public String createEntryFromForm(
            @Valid @ModelAttribute("createRequest") CreateGuestbookEntryRequest request,
            BindingResult bindingResult,
            @AuthenticationPrincipal UserDetails user,
            RedirectAttributes redirectAttributes) {

        if (bindingResult.hasErrors()) {
            log.warn("Validierungsfehler bei Gästebuch-Eintrag durch Benutzer '{}': {} Fehler",
                     user.getUsername(), bindingResult.getErrorCount());
            redirectAttributes.addFlashAttribute("org.springframework.validation.BindingResult.createRequest", bindingResult);
            redirectAttributes.addFlashAttribute("createRequest", request);
            redirectAttributes.addFlashAttribute("errorMessage", "Ungültige Eingabe. Bitte prüfen Sie Name und Text.");
            return "redirect:/guestbook";
        }

        guestbookService.createEntry(request, user.getUsername());
        redirectAttributes.addFlashAttribute("successMessage", "Eintrag erfolgreich hinzugefügt.");
        return "redirect:/guestbook";
    }

    /**
     * Zusätzlicher JSON-POST-Endpunkt für API-Clients (ebenfalls validiert und geschützt).
     */
    @PostMapping(value = "/api/guestbook", consumes = MediaType.APPLICATION_JSON_VALUE, produces = MediaType.APPLICATION_JSON_VALUE)
    @ResponseStatus(HttpStatus.CREATED)
    @ResponseBody
    public Map<String, Object> createEntryApi(
            @Valid @RequestBody CreateGuestbookEntryRequest request,
            @AuthenticationPrincipal UserDetails user) {

        GuestbookEntry saved = guestbookService.createEntry(request, user.getUsername());
        log.info("API: Eintrag {} durch '{}' erstellt", saved.getId(), user.getUsername());
        return Map.of(
            "id", saved.getId(),
            "name", saved.getName(),
            "text", saved.getText(),
            "createdAt", saved.getCreatedAt().toString()
        );
    }
}
