## 6. Security-Konfiguration

Spring Security erzwingt Authentifizierung für alle Guestbook-Endpunkte. CSRF ist für Browser-Formulare aktiv. In-Memory-User nur für Demo; in Produktion Externalized User Store + Passwort-Hashing (bereits durch `PasswordEncoder` abgedeckt). Das löst Broken Access Control und fehlende Authentifizierung.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.guestbook.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/css/**", "/js/**", "/error").permitAll()
                .requestMatchers(HttpMethod.GET, "/guestbook").authenticated()
                .requestMatchers(HttpMethod.POST, "/guestbook", "/api/guestbook").authenticated()
                .anyRequest().authenticated()
            )
            .formLogin(form -> form
                .defaultSuccessUrl("/guestbook", true)
                .permitAll()
            )
            .logout(logout -> logout
                .logoutSuccessUrl("/login?logout")
                .permitAll()
            )
            .httpBasic(Customizer.withDefaults())
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED)
            )
            // CSRF standardmäßig aktiv (wichtig für Form-POST). Für reine JSON-API ggf. selektiv deaktivieren und Token nutzen.
            .csrf(Customizer.withDefaults());

        return http.build();
    }

    @Bean
    public UserDetailsService userDetailsService(PasswordEncoder passwordEncoder) {
        UserDetails user = User.builder()
            .username("guestbookuser")
            .password(passwordEncoder.encode("ChangeMe-Secure!2024"))
            .roles("USER")
            .build();

        UserDetails admin = User.builder()
            .username("admin")
            .password(passwordEncoder.encode("ChangeMe-Admin!2024"))
            .roles("USER", "ADMIN")
            .build();

        return new InMemoryUserDetailsManager(user, admin);
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12);
    }
}
