package com.example.customer.repository;

import com.example.customer.model.Customer;
import java.util.List;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

/**
 * Repository mit ausschließlich parametrisierten JPQL-Queries.
 * Der Platzhalter :search wird von JPA/Hibernate als Bind-Parameter behandelt
 * und kann die Query-Struktur nicht verändern (Schutz vor CWE-89).
 */
@Repository
public interface CustomerRepository extends JpaRepository<Customer, Long> {

    @Query("""
            SELECT c FROM Customer c
            WHERE LOWER(c.name)  LIKE LOWER(CONCAT('%', :search, '%'))
               OR LOWER(c.email) LIKE LOWER(CONCAT('%', :search, '%'))
               OR LOWER(c.city)  LIKE LOWER(CONCAT('%', :search, '%'))
            """)
    List<Customer> searchByNameEmailOrCity(@Param("search") String search, Pageable pageable);
}
