package com.example.customer.validation;

/**
 * Zentrale Validierungsregeln. Das erlaubte Zeichenset und die Maximallänge
 * orientieren sich am Datenbankschema und verhindern überlange oder
 * strukturell gefährliche Eingaben (Defense in Depth).
 */
public final class SearchValidationConstants {

    public static final int MAX_SEARCH_LENGTH = 100;

    /**
     * Erlaubt Buchstaben (inkl. Umlaute), Ziffern, Leerzeichen, Bindestrich,
     * Apostroph, Punkt und @ (für E-Mail-Teilsuchen). Keine SQL-Metazeichen.
     */
    public static final String SEARCH_PATTERN = "^[\\p{L}\\p{N}\\s\\-'.@]{1,100}$";

    private SearchValidationConstants() {
        // Utility
    }
}
