"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerService.java
package com.example.customer.service;

import com.example.customer.dto.CustomerResponse;
import com.example.customer.model.Customer;
import com.example.customer.repository.CustomerRepository;
import com.example.customer.validation.SearchValidationConstants;
import java.util.List;
import java.util.Objects;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Service-Schicht: Validierung/Sanitisierung + Aufruf des parametrisierten Repositories.
 * Keine Query-Logik mit String-Konkatenation.
 */
@Service
public class CustomerService {

    private static final int MAX_RESULTS = 50;
    private static final Pattern SAFE_SEARCH_PATTERN =
            Pattern.compile(SearchValidationConstants.SEARCH_PATTERN);

    private final CustomerRepository customerRepository;

    public CustomerService(CustomerRepository customerRepository) {
        this.customerRepository = customerRepository;
    }

    @Transactional(readOnly = true)
    public List<CustomerResponse> searchCustomers(String rawSearch) {
        String sanitized = sanitizeAndValidate(rawSearch);

        List<Customer> entities = customerRepository.searchByNameEmailOrCity(
                sanitized,
                PageRequest.of(0, MAX_RESULTS));

        return entities.stream()
                .map(this::toResponse)
                .collect(Collectors.toList());
    }

    /**
     * Defense-in-Depth: Trim, Längenprüfung, Whitelist-Pattern.
     * Parametrisierte Queries bleiben die primäre Schutzmaßnahme gegen CWE-89.
     */
    private String sanitizeAndValidate(String rawSearch) {
        if (rawSearch == null) {
            throw new IllegalArgumentException("Search parameter must not be null");
        }

        String trimmed = rawSearch.trim();

        if (trimmed.isEmpty()) {
            throw new IllegalArgumentException("Search parameter must not be empty");
        }

        if (trimmed.length() > SearchValidationConstants.MAX_SEARCH_LENGTH) {
            throw new IllegalArgumentException(
                    "Search parameter exceeds maximum length of "
                            + SearchValidationConstants.MAX_SEARCH_LENGTH);
        }

        if (!SAFE_SEARCH_PATTERN.matcher(trimmed).matches()) {
            throw new IllegalArgumentException(
                    "Search parameter contains invalid characters");
        }

        return trimmed;
    }

    private CustomerResponse toResponse(Customer customer) {
        Objects.requireNonNull(customer, "customer must not be null");
        return new CustomerResponse(
                customer.getId(),
                customer.getName(),
                customer.getEmail(),
                customer.getCity());
    }
}
