package com.example.customer.web;

import com.example.customer.dto.CustomerResponse;
import com.example.customer.service.CustomerService;
import com.example.customer.validation.SearchValidationConstants;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.http.MediaType;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt. Eingabevalidierung erfolgt bereits auf Controller-Ebene
 * mittels Bean Validation. Die eigentliche sichere Query liegt im Service/Repository.
 */
@RestController
@RequestMapping(path = "/api/v1/customers", produces = MediaType.APPLICATION_JSON_VALUE)
@Validated
public class CustomerController {

    private final CustomerService customerService;

    public CustomerController(CustomerService customerService) {
        this.customerService = customerService;
    }

    /**
     * GET /api/v1/customers/search?search=...
     *
     * @param search Suchbegriff (name, email oder city)
     * @return JSON-Liste der treffenden Kunden (sichere Serialisierung)
     */
    @GetMapping("/search")
    public List<CustomerResponse> search(
            @RequestParam("search")
            @NotBlank(message = "search must not be blank")
            @Size(
                    max = SearchValidationConstants.MAX_SEARCH_LENGTH,
                    message = "search exceeds maximum length")
            @Pattern(
                    regexp = SearchValidationConstants.SEARCH_PATTERN,
                    message = "search contains invalid characters")
            String search) {

        return customerService.searchCustomers(search);
    }
}
