"}, {"type": "CODE_BLOCK", "language": "java", "content": "// JacksonConfig.java
package com.example.customer.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import org.springframework.http.converter.json.Jackson2ObjectMapperBuilder;

/**
 * Explizite Jackson-Konfiguration gegen CWE-943:
 * - Kein Default-Typing (verhindert polymorphe Deserialisierungsangriffe)
 * - Keine Fail-on-Empty-Beans-Überraschungen
 * - ISO-8601-Datumsformat
 */
@Configuration
public class JacksonConfig {

    @Bean
    @Primary
    public ObjectMapper objectMapper(Jackson2ObjectMapperBuilder builder) {
        ObjectMapper mapper = builder.createXmlMapper(false).build();
        mapper.registerModule(new JavaTimeModule());
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        // Default-Typing bleibt deaktiviert (Spring-Boot-Default) – bewusst nicht aktivieren
        mapper.deactivateDefaultTyping();
        return mapper;
    }
}
