import java.util.Objects;

/**
 * Immutable response DTO for a directory user.
 * Contains only non-sensitive attributes required by the API contract.
 */
public final class UserDto {

    private final String username;
    private final String displayName;
    private final String email;
    private final String department;

    public UserDto(String username, String displayName, String email, String department) {
        this.username = username;
        this.displayName = displayName;
        this.email = email;
        this.department = department;
    }

    public String getUsername() {
        return username;
    }

    public String getDisplayName() {
        return displayName;
    }

    public String getEmail() {
        return email;
    }

    public String getDepartment() {
        return department;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof UserDto)) {
            return false;
        }
        UserDto userDto = (UserDto) o;
        return Objects.equals(username, userDto.username)
                && Objects.equals(displayName, userDto.displayName)
                && Objects.equals(email, userDto.email)
                && Objects.equals(department, userDto.department);
    }

    @Override
    public int hashCode() {
        return Objects.hash(username, displayName, email, department);
    }
}
