"}, {"type": "CODE_BLOCK", "language": "java", "content": "// LdapUserService.java
package com.example.directory.service;

import com.example.directory.dto.UserDto;
import com.example.directory.exception.DirectoryServiceException;
import com.example.directory.exception.InvalidUsernameException;
import org.springframework.ldap.core.AttributesMapper;
import org.springframework.ldap.core.LdapTemplate;
import org.springframework.ldap.support.LdapNameBuilder;
import org.springframework.stereotype.Service;

import javax.naming.directory.Attributes;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Encapsulates all LDAP search logic.
 * Uses parameterized filters exclusively to eliminate LDAP-injection vectors.
 */
@Service
public class LdapUserService {

    /**
     * Allow-list: letters, digits, dot, underscore, hyphen.
     * Rejects LDAP filter metacharacters (*, (, ), \, NUL, etc.).
     */
    private static final Pattern SAFE_USERNAME = Pattern.compile("^[a-zA-Z0-9._-]+$");

    private static final String USER_SEARCH_BASE = "ou=users";
    private static final String USER_FILTER = "(&(objectClass=inetOrgPerson)(uid={0}))";

    private final LdapTemplate ldapTemplate;

    public LdapUserService(LdapTemplate ldapTemplate) {
        this.ldapTemplate = ldapTemplate;
    }

    /**
     * Searches LDAP for users whose uid matches the given username.
     *
     * @param username raw query parameter (will be validated & parameterized)
     * @return list of matching users or empty list (never null)
     */
    public List<UserDto> findUsersByUsername(String username) {
        validateUsername(username);

        try {
            return ldapTemplate.search(
                    USER_SEARCH_BASE,
                    USER_FILTER,
                    new Object[]{username},
                    (AttributesMapper<UserDto>) this::mapAttributes
            );
        } catch (Exception ex) {
            // Do not expose LDAP error details (stack traces, DNs, etc.)
            throw new DirectoryServiceException("Directory lookup failed", ex);
        }
    }

    private void validateUsername(String username) {
        if (username == null || username.isBlank()) {
            throw new InvalidUsernameException("Username must not be empty");
        }
        if (username.length() > 64) {
            throw new InvalidUsernameException("Username exceeds maximum length");
        }
        if (!SAFE_USERNAME.matcher(username).matches()) {
            throw new InvalidUsernameException("Username contains illegal characters");
        }
    }

    private UserDto mapAttributes(Attributes attrs) throws javax.naming.NamingException {
        String uid = getAttr(attrs, "uid");
        String displayName = getAttr(attrs, "displayName");
        String mail = getAttr(attrs, "mail");
        String department = getAttr(attrs, "departmentNumber");

        // Defensive defaults – never return null fields that could NPE later
        return new UserDto(
                uid != null ? uid : "",
                displayName != null ? displayName : "",
                mail != null ? mail : "",
                department != null ? department : ""
        );
    }

    private static String getAttr(Attributes attrs, String id) throws javax.naming.NamingException {
        return attrs.get(id) != null ? (String) attrs.get(id).get() : null;
    }
}
