package com.example.directory.web;

import com.example.directory.dto.UserDto;
import com.example.directory.service.LdapUserService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * REST adapter for directory lookups.
 * Keeps the controller thin: validation + delegation only.
 */
@RestController
@RequestMapping(path = "/directory", produces = MediaType.APPLICATION_JSON_VALUE)
public class DirectoryController {

    private final LdapUserService ldapUserService;

    public DirectoryController(LdapUserService ldapUserService) {
        this.ldapUserService = ldapUserService;
    }

    /**
     * GET /directory/users?username={uid}
     *
     * @param username query parameter used as LDAP uid search term
     * @return 200 + list of users (may be empty) or 400/500 via exception handler
     */
    @GetMapping("/users")
    public ResponseEntity<List<UserDto>> searchUsers(
            @RequestParam("username") String username) {

        List<UserDto> users = ldapUserService.findUsersByUsername(username);
        return ResponseEntity.ok(users);
    }
}
