package com.example.directory.web;

import com.example.directory.exception.DirectoryServiceException;
import com.example.directory.exception.InvalidUsernameException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

/**
 * Centralized exception translation.
 * Ensures consistent error bodies and prevents stack-trace leakage.
 */
@RestControllerAdvice
public class RestExceptionHandler {

    @ExceptionHandler(InvalidUsernameException.class)
    public ResponseEntity<Map<String, String>> handleInvalidUsername(InvalidUsernameException ex) {
        return ResponseEntity
                .status(HttpStatus.BAD_REQUEST)
                .body(Map.of("error", ex.getMessage()));
    }

    @ExceptionHandler(DirectoryServiceException.class)
    public ResponseEntity<Map<String, String>> handleDirectoryFailure(DirectoryServiceException ex) {
        // Log the cause server-side; client receives only a generic message
        return ResponseEntity
                .status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Map.of("error", "An internal directory error occurred"));
    }
}
