"}, {"type": "CODE_BLOCK", "language": "java", "content": "// LdapConfig.java
package com.example.directory.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.ldap.core.LdapTemplate;
import org.springframework.ldap.core.support.LdapContextSource;

/**
 * Minimal LDAP infrastructure configuration.
 * Bind credentials must be supplied via environment / secret store
 * and should follow least-privilege (read-only search account).
 */
@Configuration
public class LdapConfig {

    @Value("${ldap.url}")
    private String ldapUrl;

    @Value("${ldap.base}")
    private String ldapBase;

    @Value("${ldap.username}")
    private String ldapUsername;

    @Value("${ldap.password}")
    private String ldapPassword;

    @Bean
    public LdapContextSource contextSource() {
        LdapContextSource source = new LdapContextSource();
        source.setUrl(ldapUrl);
        source.setBase(ldapBase);
        source.setUserDn(ldapUsername);
        source.setPassword(ldapPassword);
        // Prevent anonymous binds
        source.setAnonymousReadOnly(false);
        return source;
    }

    @Bean
    public LdapTemplate ldapTemplate(LdapContextSource contextSource) {
        LdapTemplate template = new LdapTemplate(contextSource);
        // Ignore partial-result exceptions common with AD
        template.setIgnorePartialResultException(true);
        return template;
    }
}
