package com.example.export.exception;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

/**
 * Central error handling. Returns only concise, non-sensitive messages
 * to avoid CWE-209 (Generation of Error Message Containing Sensitive Information)
 * and CWE-200 (Exposure of Sensitive Information).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(InvalidFilenameException.class)
    public ResponseEntity<Map<String, String>> handleInvalidFilename(InvalidFilenameException ex) {
        log.warn("Invalid filename rejected: {}", ex.getMessage());
        return ResponseEntity
                .status(HttpStatus.BAD_REQUEST)
                .body(Map.of("error", "Invalid filename"));
    }

    @ExceptionHandler(ExportFileNotFoundException.class)
    public ResponseEntity<Map<String, String>> handleNotFound(ExportFileNotFoundException ex) {
        // Do not echo the requested name or any path fragment
        log.info("Export file not found (details suppressed in response)");
        return ResponseEntity
                .status(HttpStatus.NOT_FOUND)
                .body(Map.of("error", "File not found"));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, String>> handleGeneric(Exception ex) {
        log.error("Unexpected error during export", ex);
        return ResponseEntity
                .status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Map.of("error", "Export failed"));
    }
}
