package com.example.export.service;

import com.example.export.config.ExportProperties;
import com.example.export.exception.ExportFileNotFoundException;
import com.example.export.exception.InvalidFilenameException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.MalformedURLException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.regex.Pattern;

/**
 * Secure file resolution service.
 * Enforces whitelist filename format, canonical-path containment
 * and existence checks to mitigate CWE-22, CWE-36 and CWE-552.
 */
@Service
public class FileExportService {

    private static final Logger log = LoggerFactory.getLogger(FileExportService.class);

    /**
     * Strict whitelist: starts with alphanumeric, then only [A-Za-z0-9._-],
     * must contain a single extension. No path separators, no leading dots,
     * no empty name.
     */
    private static final Pattern SAFE_FILENAME =
            Pattern.compile("^[a-zA-Z0-9][a-zA-Z0-9._-]*\\.[a-zA-Z0-9]+$");

    private static final int MAX_FILENAME_LENGTH = 128;

    private final Path baseDir;

    public FileExportService(ExportProperties properties) throws IOException {
        this.baseDir = properties.getBaseDirPath();
        if (!Files.exists(this.baseDir)) {
            Files.createDirectories(this.baseDir);
        }
        if (!Files.isDirectory(this.baseDir) || !Files.isReadable(this.baseDir)) {
            throw new IllegalStateException("Export base directory is not usable");
        }
        log.info("Export base directory set to {}", this.baseDir);
    }

    public Resource loadAsResource(String filename) {
        validateFilename(filename);
        Path resolved = resolveSafely(filename);
        return toResource(resolved);
    }

    /**
     * Returns the original validated filename for use in Content-Disposition.
     * Only call after loadAsResource has succeeded.
     */
    public String sanitizeForHeader(String filename) {
        validateFilename(filename);
        return filename;
    }

    private void validateFilename(String filename) {
        if (filename == null || filename.isBlank()) {
            throw new InvalidFilenameException("filename is required");
        }
        if (filename.length() > MAX_FILENAME_LENGTH) {
            throw new InvalidFilenameException("filename too long");
        }
        if (!SAFE_FILENAME.matcher(filename).matches()) {
            throw new InvalidFilenameException("filename contains illegal characters or format");
        }
        // Extra defense-in-depth against encoded / traversal sequences
        String lower = filename.toLowerCase();
        if (lower.contains("..") || lower.contains("/") || lower.contains("\\")
                || lower.contains("%") || lower.contains(":") || lower.contains("\0")) {
            throw new InvalidFilenameException("filename contains illegal sequences");
        }
    }

    private Path resolveSafely(String filename) {
        try {
            // Resolve against base and normalize (removes ./ ../)
            Path candidate = baseDir.resolve(filename).normalize();

            // Canonical / real path comparison prevents symlink and case-trick escapes
            Path realBase = baseDir.toRealPath();
            Path realCandidate = candidate.toRealPath();

            if (!realCandidate.startsWith(realBase)) {
                log.warn("Path traversal attempt blocked for input '{}'", filename);
                throw new InvalidFilenameException("path outside export directory");
            }

            if (!Files.isRegularFile(realCandidate) || !Files.isReadable(realCandidate)) {
                throw new ExportFileNotFoundException("not a readable file");
            }

            return realCandidate;
        } catch (IOException ex) {
            // File does not exist or is not reachable → treat as not found
            throw new ExportFileNotFoundException("file not accessible");
        }
    }

    private Resource toResource(Path file) {
        try {
            Resource resource = new UrlResource(file.toUri());
            if (!resource.exists() || !resource.isReadable()) {
                throw new ExportFileNotFoundException("resource not readable");
            }
            return resource;
        } catch (MalformedURLException ex) {
            throw new ExportFileNotFoundException("invalid resource URL");
        }
    }
}
