package com.example.export.web;

import com.example.export.service.FileExportService;
import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST endpoint GET /export?filename=...
 *
 * Security measures:
 * - Filename whitelist + length limit (CWE-22)
 * - Canonical path containment inside exports/ (CWE-36, CWE-552)
 * - Content-Disposition with sanitized filename only (CWE-200)
 * - Generic error bodies via GlobalExceptionHandler (CWE-209)
 *
 * Access control (authentication/authorization) must still be applied
 * at the security-filter or method-security layer (A01:2025).
 */
@RestController
public class ExportController {

    private final FileExportService fileExportService;

    public ExportController(FileExportService fileExportService) {
        this.fileExportService = fileExportService;
    }

    @GetMapping("/export")
    public ResponseEntity<Resource> export(@RequestParam("filename") String filename) {
        Resource resource = fileExportService.loadAsResource(filename);
        String safeName = fileExportService.sanitizeForHeader(filename);

        // Only the validated basename is sent; no path, no server details
        String contentDisposition = "attachment; filename=\"" + safeName + "\"";

        return ResponseEntity.ok()
                .header(HttpHeaders.CONTENT_DISPOSITION, contentDisposition)
                .header(HttpHeaders.X_CONTENT_TYPE_OPTIONS, "nosniff")
                .header(HttpHeaders.CACHE_CONTROL, "no-store")
                .contentType(MediaType.APPLICATION_OCTET_STREAM)
                .body(resource);
    }
}
