package com.example.redirectsecurity.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;
import org.springframework.validation.annotation.Validated;

import jakarta.validation.constraints.NotEmpty;
import java.util.ArrayList;
import java.util.List;

@Component
@ConfigurationProperties(prefix = "app.redirect")
@Validated
public class RedirectProperties {

    /**
     * Erlaubte Hosts (Allow-List). Nur exakte Hostnamen, z. B. "app.example.com".
     * Keine Wildcards in der Basisimplementierung – reduziert Angriffsfläche.
     */
    @NotEmpty
    private List<String> allowedHosts = new ArrayList<>();

    /**
     * Erlaubte URL-Pfad-Präfixe pro Host (optional einschränkend).
     * Leer = alle Pfade auf erlaubten Hosts sind gestattet (nach Scheme-/Strukturprüfung).
     */
    private List<String> allowedPathPrefixes = new ArrayList<>();

    /**
     * Maximale Länge der redirectUrl, um DoS durch extrem lange Strings zu begrenzen.
     */
    private int maxUrlLength = 2048;

    public List<String> getAllowedHosts() {
        return allowedHosts;
    }

    public void setAllowedHosts(List<String> allowedHosts) {
        this.allowedHosts = allowedHosts != null ? allowedHosts : new ArrayList<>();
    }

    public List<String> getAllowedPathPrefixes() {
        return allowedPathPrefixes;
    }

    public void setAllowedPathPrefixes(List<String> allowedPathPrefixes) {
        this.allowedPathPrefixes = allowedPathPrefixes != null ? allowedPathPrefixes : new ArrayList<>();
    }

    public int getMaxUrlLength() {
        return maxUrlLength;
    }

    public void setMaxUrlLength(int maxUrlLength) {
        this.maxUrlLength = maxUrlLength;
    }
}
