package com.example.redirectsecurity.service;

import com.example.redirectsecurity.config.RedirectProperties;
import com.example.redirectsecurity.exception.InvalidRedirectException;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;
import java.util.Set;

/**
 * Validiert redirectUrl ausschließlich gegen eine serverseitige Allow-List.
 * Verhindert Open Redirects (CWE-601) und unsichere URL-Schemes.
 */
@Service
public class RedirectValidationService {

    private static final Set<String> ALLOWED_SCHEMES = Set.of("https");

    private final RedirectProperties properties;

    public RedirectValidationService(RedirectProperties properties) {
        this.properties = properties;
    }

    /**
     * Prüft und normalisiert die übergebene redirectUrl.
     * Bei jedem Verstoß wird InvalidRedirectException geworfen – es wird nie eine
     * ungeprüfte URL zurückgegeben.
     */
    public String validateAndSanitize(String redirectUrl) {
        if (!StringUtils.hasText(redirectUrl)) {
            throw new InvalidRedirectException("redirectUrl must not be empty");
        }

        String trimmed = redirectUrl.trim();
        if (trimmed.length() > properties.getMaxUrlLength()) {
            throw new InvalidRedirectException("redirectUrl exceeds maximum allowed length");
        }

        // Verbot gefährlicher oder mehrdeutiger Zeichenfolgen früh abfangen
        String lower = trimmed.toLocaleLowerCase(Locale.ROOT);
        if (lower.contains("javascript:")
                || lower.contains("data:")
                || lower.contains("vbscript:")
                || lower.contains("%00")
                || lower.contains("\\")) {
            throw new InvalidRedirectException("redirectUrl contains disallowed content");
        }

        final URI uri;
        try {
            uri = new URI(trimmed);
        } catch (URISyntaxException ex) {
            throw new InvalidRedirectException("redirectUrl is not a valid URI");
        }

        // Nur absolute URLs mit erlaubtem Scheme (kein Protocol-Relative //evil.com)
        if (!uri.isAbsolute()) {
            throw new InvalidRedirectException("redirectUrl must be an absolute URL");
        }

        String scheme = uri.getScheme();
        if (scheme == null || !ALLOWED_SCHEMES.contains(scheme.toLowerCase(Locale.ROOT))) {
            throw new InvalidRedirectException("redirectUrl scheme is not allowed");
        }

        String host = uri.getHost();
        if (host == null || host.isBlank()) {
            throw new InvalidRedirectException("redirectUrl host is missing");
        }

        // Host muss exakt in der Allow-List stehen (keine Subdomain-Tricks ohne expliziten Eintrag)
        String normalizedHost = host.toLowerCase(Locale.ROOT);
        boolean hostAllowed = properties.getAllowedHosts().stream()
                .map(h -> h.toLowerCase(Locale.ROOT))
                .anyMatch(normalizedHost::equals);
        if (!hostAllowed) {
            throw new InvalidRedirectException("redirectUrl host is not in the allow-list");
        }

        // UserInfo (user:pass@host) unterbinden – klassischer Open-Redirect-/Phishing-Vektor
        if (uri.getUserInfo() != null) {
            throw new InvalidRedirectException("redirectUrl must not contain user info");
        }

        // Optionale Pfad-Präfix-Prüfung
        if (!properties.getAllowedPathPrefixes().isEmpty()) {
            String path = uri.getPath() != null ? uri.getPath() : "/";
            boolean pathAllowed = properties.getAllowedPathPrefixes().stream()
                    .anyMatch(path::startsWith);
            if (!pathAllowed) {
                throw new InvalidRedirectException("redirectUrl path is not allowed");
            }
        }

        // Fragment und ungewöhnliche Port-Angaben: für Redirects oft unnötig; hier behalten wir
        // die normalisierte ASCII-Form der URI, ohne zusätzliche Client-Steuerung.
        // toASCIIString() verhindert IDN-/Encoding-Überraschungen.
        return uri.toASCIIString();
    }
}
