package com.example.redirectsecurity.service;

import com.example.redirectsecurity.exception.RateLimitExceededException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Einfaches In-Memory-Rate-Limiting pro Client-Schlüssel (z. B. IP).
 * Begrenzt Missbrauch und Ressourcenerschöpfung (CWE-400).
 * Für verteilte Systeme durch Bucket4j + Redis o. Ä. ersetzen.
 */
@Service
public class RateLimitService {

    private final long capacity;
    private final long refillTokensPerSecond;
    private final ConcurrentHashMap<String, TokenBucket> buckets = new ConcurrentHashMap<>();

    public RateLimitService(
            @Value("${app.redirect.rate-limit.capacity:20}") long capacity,
            @Value("${app.redirect.rate-limit.refill-per-second:5}") long refillTokensPerSecond) {
        if (capacity < 1 || refillTokensPerSecond < 1) {
            throw new IllegalArgumentException("Rate limit parameters must be positive");
        }
        this.capacity = capacity;
        this.refillTokensPerSecond = refillTokensPerSecond;
    }

    public void checkRateLimit(String clientKey) {
        if (clientKey == null || clientKey.isBlank()) {
            throw new RateLimitExceededException("Unable to determine client identity");
        }
        TokenBucket bucket = buckets.computeIfAbsent(clientKey, k -> new TokenBucket(capacity, refillTokensPerSecond));
        if (!bucket.tryConsume()) {
            throw new RateLimitExceededException("Rate limit exceeded. Try again later.");
        }
    }

    /**
     * Sehr schlanker Token-Bucket ohne externe Bibliothek.
     * Nicht für Multi-Node-Cluster gedacht (dort shared store verwenden).
     */
    private static final class TokenBucket {
        private final long capacity;
        private final long refillPerSecond;
        private final AtomicLong tokens;
        private final AtomicLong lastRefillNanos;

        TokenBucket(long capacity, long refillPerSecond) {
            this.capacity = capacity;
            this.refillPerSecond = refillPerSecond;
            this.tokens = new AtomicLong(capacity);
            this.lastRefillNanos = new AtomicLong(System.nanoTime());
        }

        boolean tryConsume() {
            refill();
            long current;
            do {
                current = tokens.get();
                if (current <= 0) {
                    return false;
                }
            } while (!tokens.compareAndSet(current, current - 1));
            return true;
        }

        private void refill() {
            long now = System.nanoTime();
            long last = lastRefillNanos.get();
            long elapsedNanos = now - last;
            if (elapsedNanos <= 0) {
                return;
            }
            long tokensToAdd = (elapsedNanos * refillPerSecond) / 1_000_000_000L;
            if (tokensToAdd > 0 && lastRefillNanos.compareAndSet(last, now)) {
                tokens.updateAndGet(t -> Math.min(capacity, t + tokensToAdd));
            }
        }
    }
}
