"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectController.java
package com.example.redirectsecurity.web;

import com.example.redirectsecurity.service.RateLimitService;
import com.example.redirectsecurity.service.RedirectValidationService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * Sicherer Redirect-Endpunkt: Location-Header nur nach Allow-List-Validierung.
 * Kein unvalidiertes sendRedirect / keine offenen Forwards.
 */
@RestController
@RequestMapping("/api/v1")
public class RedirectController {

    private final RedirectValidationService validationService;
    private final RateLimitService rateLimitService;

    public RedirectController(
            RedirectValidationService validationService,
            RateLimitService rateLimitService) {
        this.validationService = validationService;
        this.rateLimitService = rateLimitService;
    }

    /**
     * GET /api/v1/redirect?redirectUrl=https://app.example.com/dashboard
     *
     * Bei Erfolg: 302 Found + Location-Header (Frontend kann folgen).
     * Bei Fehler: 400 oder 429 ohne Location-Header.
     */
    @GetMapping("/redirect")
    public ResponseEntity<Void> redirect(
            @RequestParam("redirectUrl") String redirectUrl,
            HttpServletRequest request) {

        String clientKey = resolveClientKey(request);
        rateLimitService.checkRateLimit(clientKey);

        String safeLocation = validationService.validateAndSanitize(redirectUrl);

        return ResponseEntity
                .status(HttpStatus.FOUND)
                .header(HttpHeaders.LOCATION, safeLocation)
                .build();
    }

    /**
     * Bevorzugt X-Forwarded-For nur wenn die Anwendung hinter einem vertrauenswürdigen
     * Proxy liegt und dieser korrekt konfiguriert ist. Sonst Remote-Addr.
     */
    private String resolveClientKey(HttpServletRequest request) {
        String forwarded = request.getHeader("X-Forwarded-For");
        if (forwarded != null && !forwarded.isBlank()) {
            // Ersten Hop nehmen; in Produktion Proxy-Trust-Listen verwenden
            String first = forwarded.split(",")[0].trim();
            if (!first.isEmpty()) {
                return first;
            }
        }
        String remote = request.getRemoteAddr();
        return remote != null ? remote : "unknown";
    }
}
