"}, {"type": "CODE_BLOCK", "language": "java", "content": "// HostValidator.java
package com.example.securefetch.security;

import com.example.securefetch.config.HostWhitelistProperties;
import com.example.securefetch.exception.HostValidationException;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;

import java.net.IDN;
import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Validiert Benutzer-Hosts gegen eine Whitelist, bevor DNS oder TLS genutzt werden.
 * Mindert DNS-Rebinding (CWE-180) und SSRF (CWE-918), indem nur explizit erlaubte
 * Domains/IPs akzeptiert werden. Kanonisierung (Lowercase, IDN/Punycode, Trim)
 * erfolgt vor dem Vergleich.
 */
@Component
public class HostValidator {

    private static final Pattern HOST_PATTERN = Pattern.compile(
            "^(?=.{1,253}$)(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*\\.?$"
    );
    private static final Pattern IPV4_PATTERN = Pattern.compile(
            "^((25[0-5]|2[0-4]\\d|[01]?\\d\\d?)\\.){3}(25[0-5]|2[0-4]\\d|[01]?\\d\\d?)$"
    );

    private final HostWhitelistProperties whitelistProperties;

    public HostValidator(HostWhitelistProperties whitelistProperties) {
        this.whitelistProperties = whitelistProperties;
    }

    /**
     * Prüft und normalisiert den Host. Liefert den kanonischen Host zurück,
     * der anschließend für den HTTPS-Aufruf verwendet werden darf.
     */
    public String validateAndNormalize(String rawHost) {
        if (!StringUtils.hasText(rawHost)) {
            throw new HostValidationException("Host-Parameter darf nicht leer sein.");
        }

        String host = rawHost.trim().toLowerCase(Locale.ROOT);

        // Keine URL, kein Schema, kein Pfad, kein Userinfo – nur reiner Host
        if (host.contains("://") || host.contains("/") || host.contains("@")
                || host.contains("?") || host.contains("#") || host.contains("\\")) {
            throw new HostValidationException("Host darf kein Schema, Pfad oder Userinfo enthalten.");
        }

        // Optionalen Port entfernen und verbieten (Port steuern wir serverseitig)
        int colon = host.indexOf(':');
        if (colon >= 0) {
            throw new HostValidationException("Explizite Ports im Host sind nicht erlaubt.");
        }

        // IPv6 in Klammern nicht freigeben ohne Whitelist-Treffer; hier bewusst nur IPv4/Hostname
        if (host.startsWith("[") || host.contains(":")) {
            throw new HostValidationException("IPv6-Literale sind in dieser Konfiguration nicht freigeschaltet.");
        }

        try {
            // IDN → Punycode (verhindert Homographen-Tricks)
            host = IDN.toASCII(host, IDN.USE_STD3_ASCII_RULES);
        } catch (IllegalArgumentException ex) {
            throw new HostValidationException("Host enthält ungültige Internationalized-Domain-Zeichen.", ex);
        }

        host = host.toLowerCase(Locale.ROOT);

        boolean isIp = IPV4_PATTERN.matcher(host).matches();
        if (!isIp && !HOST_PATTERN.matcher(host).matches()) {
            throw new HostValidationException("Host hat ein ungültiges Format.");
        }

        if (!isAllowed(host, isIp)) {
            throw new HostValidationException("Host ist nicht in der Whitelist der erlaubten Ziele.");
        }

        // Zusätzliche Absicherung gegen DNS-Rebinding: nach Auflösung erneut prüfen
        // (IP muss zur Whitelist passen bzw. der Name weiterhin erlaubt sein).
        verifyResolvedAddresses(host, isIp);

        return host;
    }

    private boolean isAllowed(String host, boolean isIp) {
        for (String entry : whitelistProperties.getAllowedHosts()) {
            if (!StringUtils.hasText(entry)) {
                continue;
            }
            String allowed = entry.trim().toLowerCase(Locale.ROOT);
            try {
                allowed = IDN.toASCII(allowed, IDN.USE_STD3_ASCII_RULES).toLowerCase(Locale.ROOT);
            } catch (IllegalArgumentException ignored) {
                continue;
            }

            if (isIp) {
                if (allowed.equals(host)) {
                    return true;
                }
            } else {
                // Exakter Match oder Suffix-Match für ".example.com"
                if (allowed.startsWith(".")) {
                    if (host.endsWith(allowed) || host.equals(allowed.substring(1))) {
                        return true;
                    }
                } else if (allowed.equals(host)) {
                    return true;
                }
            }
        }
        return false;
    }

    private void verifyResolvedAddresses(String host, boolean isIp) {
        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            if (addresses == null || addresses.length == 0) {
                throw new HostValidationException("Host konnte nicht aufgelöst werden.");
            }
            for (InetAddress addr : addresses) {
                // Blockiere typische interne/link-lokale Ziele zusätzlich zur Whitelist
                if (addr.isAnyLocalAddress() || addr.isLoopbackAddress()
                        || addr.isLinkLocalAddress() || addr.isSiteLocalAddress()
                        || addr.isMulticastAddress()) {
                    // Nur erlauben, wenn die IP explizit auf der Whitelist steht
                    String ip = addr.getHostAddress();
                    if (!isAllowed(ip, true)) {
                        throw new HostValidationException(
                                "Aufgelöste Adresse liegt in einem nicht freigegebenen Adressbereich.");
                    }
                }
                // Bei Hostnamen: aufgelöste IP muss nicht zwingend whitelisted sein,
                // der Name war es bereits – das verhindert klassisches Rebinding auf interne Netze
                // in Kombination mit der Private-IP-Sperre oben.
                if (isIp && !isAllowed(addr.getHostAddress(), true)) {
                    throw new HostValidationException("IP-Adresse ist nicht freigegeben.");
                }
            }
        } catch (UnknownHostException ex) {
            throw new HostValidationException("Host-DNS-Auflösung fehlgeschlagen.", ex);
        }
    }
}
