"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureWebClientConfig.java
package com.example.securefetch.config;

import io.netty.handler.ssl.SslContext;
import io.netty.handler.ssl.SslContextBuilder;
import io.netty.handler.ssl.SslProvider;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.reactive.ReactorClientHttpConnector;
import org.springframework.web.reactive.function.client.ExchangeStrategies;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.netty.http.client.HttpClient;
import reactor.netty.resources.ConnectionProvider;

import javax.net.ssl.SSLException;
import java.time.Duration;
import java.util.List;

/**
 * Baut einen WebClient mit strikter TLS-Konfiguration gemäß OWASP TLS Cheat Sheet:
 * - Nur TLS 1.2 und TLS 1.3
 * - Starke Cipher-Suites (AEAD/GCM bzw. TLS1.3-Suites)
 * - Standard-Truststore und aktive Hostname-Verification (Schutz vor MITM, CWE-295)
 * - Keine Kompression auf Anwendungsebene über diesen Client
 */
@Configuration
public class SecureWebClientConfig {

    private static final List<String> ENABLED_PROTOCOLS = List.of("TLSv1.2", "TLSv1.3");

    /**
     * Moderne, interoperable Cipher-Suites (Mozilla intermediate / modern angelehnt).
     * Null-, Export-, Anonymous- und Legacy-CBC-Suites sind bewusst nicht enthalten.
     */
    private static final List<String> ENABLED_CIPHERS = List.of(
            // TLS 1.3
            "TLS_AES_256_GCM_SHA384",
            "TLS_AES_128_GCM_SHA256",
            "TLS_CHACHA20_POLY1305_SHA256",
            // TLS 1.2 GCM / ChaCha
            "TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384",
            "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
            "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256",
            "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
            "TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305_SHA256",
            "TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305_SHA256"
    );

    @Bean
    public WebClient secureWebClient(WebClient.Builder builder) throws SSLException {
        SslContext sslContext = SslContextBuilder.forClient()
                .sslProvider(SslProvider.JDK)
                .protocols(ENABLED_PROTOCOLS.toArray(String[]::new))
                .ciphers(ENABLED_CIPHERS)
                // TrustManager = JVM-Default-Truststore; Hostname-Verification bleibt aktiv
                .build();

        ConnectionProvider connectionProvider = ConnectionProvider.builder("secure-external-pool")
                .maxConnections(50)
                .pendingAcquireTimeout(Duration.ofSeconds(10))
                .maxIdleTime(Duration.ofSeconds(30))
                .build();

        HttpClient httpClient = HttpClient.create(connectionProvider)
                .secure(sslSpec -> sslSpec.sslContext(sslContext))
                .responseTimeout(Duration.ofSeconds(15))
                .followRedirect(false);

        ExchangeStrategies strategies = ExchangeStrategies.builder()
                .codecs(cfg -> cfg.defaultCodecs().maxInMemorySize(2 * 1024 * 1024))
                .build();

        return builder
                .clientConnector(new ReactorClientHttpConnector(httpClient))
                .exchangeStrategies(strategies)
                .build();
    }
}
