"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ExternalResourceService.java
package com.example.securefetch.service;

import com.example.securefetch.exception.ExternalFetchException;
import com.example.securefetch.security.HostValidator;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.web.reactive.function.client.WebClient;
import org.springframework.web.reactive.function.client.WebClientRequestException;
import org.springframework.web.reactive.function.client.WebClientResponseException;

import java.net.URI;
import java.time.Duration;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

/**
 * Orchestriert Validierung, Allowlist-Auflösung und den HTTPS-Abruf.
 * Ziel-URIs stammen ausschließlich aus einer statischen Allowlist und werden
 * niemals aus nutzergesteuerten Zeichenketten zusammengesetzt (SSRF-Schutz).
 */
@Service
public class ExternalResourceService {

    private final WebClient secureWebClient;
    private final HostValidator hostValidator;

    /**
     * Kanonische Allowlist: Schlüssel = normalisierter Hostname,
     * Wert = fest verdrahtete HTTPS-URI (kein User-Input im URI-Bau).
     * Nur diese vordefinierten Ziele sind erreichbar.
     */
    private static final Map<String, URI> ALLOWED_HOST_URIS = Map.of(
            // Einträge bei Bedarf erweitern; Hosts müssen mit HostValidator übereinstimmen.
            "api.trusted.example", URI.create("https://api.trusted.example/"),
            "cdn.trusted.example", URI.create("https://cdn.trusted.example/")
    );

    public ExternalResourceService(WebClient secureWebClient, HostValidator hostValidator) {
        this.secureWebClient = secureWebClient;
        this.hostValidator = hostValidator;
    }

    /**
     * Validiert den Host gegen den Validator und die lokale Allowlist,
     * wählt ausschließlich die vordefinierte URI und liefert den Response-Body.
     */
    public String fetchFromHost(String rawHost) {
        if (rawHost == null || rawHost.isBlank()) {
            throw new ExternalFetchException("Host darf nicht leer sein.");
        }

        final String normalizedHost = hostValidator.validateAndNormalize(rawHost);
        final String lookupKey = normalizedHost.toLowerCase(Locale.ROOT);

        // URI kommt nur aus der Allowlist-Konstante – bricht die Taint-Kette (CWE-918).
        final URI targetUri = Optional.ofNullable(ALLOWED_HOST_URIS.get(lookupKey))
                .orElseThrow(() -> new ExternalFetchException(
                        "Host ist nicht in der Allowlist freigegeben."));

        assertSafeTarget(targetUri, lookupKey);

        try {
            return secureWebClient.get()
                    .uri(targetUri)
                    .accept(MediaType.APPLICATION_JSON, MediaType.TEXT_PLAIN)
                    .retrieve()
                    .bodyToMono(String.class)
                    .timeout(Duration.ofSeconds(20))
                    .block();
        } catch (WebClientResponseException ex) {
            throw new ExternalFetchException(
                    "Zielsystem antwortete mit HTTP " + ex.getStatusCode().value(), ex);
        } catch (WebClientRequestException ex) {
            throw new ExternalFetchException(
                    "Sichere Verbindung zum Ziel fehlgeschlagen (TLS/Netzwerk).", ex);
        } catch (ExternalFetchException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new ExternalFetchException("Unerwarteter Fehler beim Abruf.", ex);
        }
    }

    /**
     * Defense-in-Depth: Schema, Host und Struktur der Allowlist-URI prüfen,
     * bevor ein Request ausgelöst wird.
     */
    private static void assertSafeTarget(URI targetUri, String expectedHost) {
        if (!"https".equalsIgnoreCase(targetUri.getScheme())) {
            throw new ExternalFetchException("Nur HTTPS-Ziele sind erlaubt.");
        }
        if (targetUri.getUserInfo() != null) {
            throw new ExternalFetchException("URI mit User-Info ist nicht erlaubt.");
        }
        if (targetUri.getHost() == null
                || !expectedHost.equals(targetUri.getHost().toLowerCase(Locale.ROOT))) {
            throw new ExternalFetchException("URI-Host weicht von der Allowlist ab.");
        }
        if (targetUri.getPort() != -1 && targetUri.getPort() != 443) {
            throw new ExternalFetchException("Nur Standard-HTTPS-Port 443 ist erlaubt.");
        }
        // Keine offenen Redirect-Ziele über Query/Fragment aus Allowlist-Werten
        if (targetUri.getQuery() != null || targetUri.getFragment() != null) {
            throw new ExternalFetchException("Query/Fragment in Ziel-URI sind nicht erlaubt.");
        }
    }
}
