"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ExternalResourceController.java
package com.example.securefetch.web;

import com.example.securefetch.service.ExternalResourceService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt: nimmt einen Host entgegen, validiert ihn und proxied den HTTPS-Abruf.
 * Keine gemischten HTTP/HTTPS-Inhalte; Antwort wird nur über TLS an den Client ausgeliefert
 * (Voraussetzung: Spring-Boot-Server selbst mit TLS bzw. hinter TLS-Terminator).
 */
@RestController
@RequestMapping(path = "/api/v1/external", produces = MediaType.APPLICATION_JSON_VALUE)
@Validated
public class ExternalResourceController {

    private final ExternalResourceService externalResourceService;

    public ExternalResourceController(ExternalResourceService externalResourceService) {
        this.externalResourceService = externalResourceService;
    }

    /**
     * GET /api/v1/external/fetch?host=api.example.com
     *
     * @param host reiner Hostname oder IPv4-Adresse aus der Whitelist (ohne Schema/Port/Pfad)
     */
    @GetMapping(path = "/fetch", produces = {MediaType.APPLICATION_JSON_VALUE, MediaType.TEXT_PLAIN_VALUE})
    public ResponseEntity<String> fetch(@RequestParam("host") String host) {
        String body = externalResourceService.fetchFromHost(host);
        return ResponseEntity.ok()
                .header("Cache-Control", "no-cache, no-store, must-revalidate")
                .header("Pragma", "no-cache")
                .header("Expires", "0")
                .body(body);
    }
}
