"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FingerprintService.java
package com.example.fingerprint;

import org.springframework.stereotype.Service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Service zur Berechnung eines stabilen, fest langen kryptographischen Fingerprints.
 * Verwendet SHA-256 (feste 256-Bit-Ausgabe) ohne Salt, um Determinismus zu gewährleisten
 * und Length-Extension-Angriffe auf secret||message-Konstrukte zu vermeiden.
 */
@Service
public class FingerprintService {

    private static final String HASH_ALGORITHM = "SHA-256";
    private static final int MAX_VALUE_LENGTH = 4096;

    /**
     * Berechnet einen hexadezimalen SHA-256-Fingerprint des übergebenen Werts.
     *
     * @param value der zu hashende Wert (darf nicht null/leer sein und muss Längenlimit einhalten)
     * @return 64-stelliger Hex-String (feste Länge)
     * @throws IllegalArgumentException bei ungültiger Eingabe
     * @throws IllegalStateException   bei unerwarteten Krypto-Problemen (sollte in der Praxis nicht auftreten)
     */
    public String computeFingerprint(String value) {
        if (value == null || value.isEmpty()) {
            throw new IllegalArgumentException("Value must not be null or empty");
        }
        if (value.length() > MAX_VALUE_LENGTH) {
            throw new IllegalArgumentException("Value exceeds maximum allowed length");
        }

        try {
            MessageDigest digest = MessageDigest.getInstance(HASH_ALGORITHM);
            byte[] hashBytes = digest.digest(value.getBytes(StandardCharsets.UTF_8));
            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException ex) {
            // Sehr unwahrscheinlich bei Standard-JREs; wird vom GlobalExceptionHandler generisch behandelt
            throw new IllegalStateException("Cryptographic algorithm unavailable", ex);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
