"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FingerprintController.java
package com.example.fingerprint;

import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Controller für den /fingerprint-Endpunkt.
 * Nimmt den Query-Parameter entgegen und delegiert die Hash-Berechnung an den Service.
 */
@RestController
public class FingerprintController {

    private final FingerprintService fingerprintService;

    public FingerprintController(FingerprintService fingerprintService) {
        this.fingerprintService = fingerprintService;
    }

    /**
     * GET /fingerprint?value=...
     * Liefert einen stabilen SHA-256-Hex-Fingerprint als Plain-String.
     */
    @GetMapping(value = "/fingerprint", produces = MediaType.TEXT_PLAIN_VALUE)
    public ResponseEntity<String> fingerprint(@RequestParam("value") String value) {
        String hash = fingerprintService.computeFingerprint(value);
        return ResponseEntity.ok(hash);
    }
}
