"}, {"type": "CODE_BLOCK", "language": "java", "content": "// KeyManagementService.java
package com.example.securenotes.service;

import com.example.securenotes.config.KeyStoreProperties;
import com.example.securenotes.exception.NoteEncryptionException;
import org.springframework.stereotype.Service;

import javax.crypto.Mac;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.io.FileInputStream;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;

/**
 * Lädt den Master-Key ausschließlich aus einem Java-KeyStore
 * und leitet daraus benutzerspezifische AES-256-Schlüssel ab (HMAC-based KDF).
 * Verhindert Key-Exposure (CWE-321) und ermöglicht deterministische Ableitung.
 */
@Service
public class KeyManagementService {

    private final SecretKey masterKey;

    public KeyManagementService(KeyStoreProperties properties) {
        this.masterKey = loadMasterKey(properties);
    }

    private SecretKey loadMasterKey(KeyStoreProperties properties) {
        try {
            KeyStore keyStore = KeyStore.getInstance("PKCS12");
            try (FileInputStream fis = new FileInputStream(properties.getPath())) {
                keyStore.load(fis, properties.getPassword().toCharArray());
            }
            KeyStore.ProtectionParameter protection =
                    new KeyStore.PasswordProtection(properties.getKeyPassword().toCharArray());
            KeyStore.SecretKeyEntry entry =
                    (KeyStore.SecretKeyEntry) keyStore.getEntry(properties.getAlias(), protection);
            if (entry == null) {
                throw new IllegalStateException("Alias not found in KeyStore: " + properties.getAlias());
            }
            return entry.getSecretKey();
        } catch (Exception ex) {
            throw new IllegalStateException("Unable to load master key from KeyStore", ex);
        }
    }

    /**
     * Leitet einen deterministischen AES-256-Schlüssel aus Master-Key + userId ab.
     */
    public SecretKey deriveUserKey(String userId) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(masterKey);
            byte[] rawKey = mac.doFinal(userId.getBytes(StandardCharsets.UTF_8));
            return new SecretKeySpec(rawKey, "AES");
        } catch (Exception ex) {
            throw new NoteEncryptionException("User key derivation failed", ex);
        }
    }
}
