"}, {"type": "CODE_BLOCK", "language": "java", "content": "// NoteEncryptionService.java
package com.example.securenotes.service;

import com.example.securenotes.dto.EncryptNoteResponse;
import com.example.securenotes.exception.NoteEncryptionException;
import org.springframework.stereotype.Service;

import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;

/**
 * Führt die symmetrische Verschlüsselung mit AES-256-GCM durch.
 * IV wird deterministisch aus HMAC(userKey, plaintext) abgeleitet,
 * wodurch gleiche (userId, text)-Paare denselben Ciphertext erzeugen,
 * ohne Nonce-Reuse bei unterschiedlichen Plaintexts zu riskieren.
 */
@Service
public class NoteEncryptionService {

    private static final int GCM_IV_LENGTH = 12;
    private static final int GCM_TAG_BITS = 128;
    private static final String TRANSFORMATION = "AES/GCM/NoPadding";

    private final KeyManagementService keyManagementService;

    public NoteEncryptionService(KeyManagementService keyManagementService) {
        this.keyManagementService = keyManagementService;
    }

    public EncryptNoteResponse encrypt(String text, String userId) {
        try {
            SecretKey userKey = keyManagementService.deriveUserKey(userId);
            byte[] plainBytes = text.getBytes(StandardCharsets.UTF_8);

            byte[] iv = deriveDeterministicIv(userKey, plainBytes);

            Cipher cipher = Cipher.getInstance(TRANSFORMATION);
            GCMParameterSpec gcmSpec = new GCMParameterSpec(GCM_TAG_BITS, iv);
            cipher.init(Cipher.ENCRYPT_MODE, userKey, gcmSpec);
            byte[] cipherBytes = cipher.doFinal(plainBytes);

            // IV || (ciphertext + GCM-Tag)
            ByteBuffer buffer = ByteBuffer.allocate(iv.length + cipherBytes.length);
            buffer.put(iv);
            buffer.put(cipherBytes);
            String encryptedBase64 = Base64.getEncoder().encodeToString(buffer.array());

            return new EncryptNoteResponse(encryptedBase64, userId);
        } catch (Exception ex) {
            throw new NoteEncryptionException("Encryption operation failed", ex);
        }
    }

    /**
     * Deterministische IV-Ableitung: erste 12 Byte von HMAC-SHA256(key, plaintext).
     * Garantiert Eindeutigkeit pro Plaintext bei gleichem Schlüssel.
     */
    private byte[] deriveDeterministicIv(SecretKey key, byte[] plaintext) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(key);
        byte[] hmac = mac.doFinal(plaintext);
        return Arrays.copyOf(hmac, GCM_IV_LENGTH);
    }
}
