package com.example.securenotes.controller;

import com.example.securenotes.dto.EncryptNoteRequest;
import com.example.securenotes.dto.EncryptNoteResponse;
import com.example.securenotes.service.NoteEncryptionService;
import com.example.securenotes.validation.UserIdValidator;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt POST /api/notes/encrypt.
 * Optionaler userId-Query-Parameter; bei Abwesenheit wird ein sicherer Default verwendet.
 */
@RestController
@RequestMapping("/api/notes")
public class NoteController {

    private static final String DEFAULT_USER_ID = "default";

    private final NoteEncryptionService noteEncryptionService;

    public NoteController(NoteEncryptionService noteEncryptionService) {
        this.noteEncryptionService = noteEncryptionService;
    }

    @PostMapping("/encrypt")
    public ResponseEntity<EncryptNoteResponse> encryptNote(
            @Valid @RequestBody EncryptNoteRequest request,
            @RequestParam(value = "userId", required = false) String userId) {

        String effectiveUserId = (userId == null || userId.isBlank())
                ? DEFAULT_USER_ID
                : userId.trim();

        // Allowlist-Validierung gegen Injection (CWE-89)
        UserIdValidator.validate(effectiveUserId);

        EncryptNoteResponse response = noteEncryptionService.encrypt(request.getText(), effectiveUserId);
        return ResponseEntity.ok(response);
    }
}
