[{"type": "TEXT", "text": "Das Design folgt einem klassischen Spring-Boot-Schichtenmodell (Controller → Service → Repository) mit einer persistenten Singleton-Einstellungen-Entität. Der Endpoint ist als Management-Endpoint konzipiert und daher bewusst abgesichert: nur `POST`, strikte Content-Type-Prüfung, Bean Validation, Whitelist-Validierung kritischer Felder, generische Fehlerantworten und rollenbasierte Zugriffskontrolle. Damit werden u. a. OWASP A01 (Broken Access Control), A03 (Injection), A04 (Insecure Design bzgl. Out-of-Order/Initialisierung), A05 (Security Misconfiguration) und typische CWE-20/CWE-116/CWE-770-Risiken adressiert.

Die Einstellungen liegen als genau eine Zeile in der Datenbank (ID fest = 1). Beim ersten Aufruf werden Defaults angelegt und mit dem Request gemerged; fehlende Felder behalten den Default bzw. den bereits gespeicherten Wert. Nach der Initialisierung lehnt der Endpoint weitere Schreibversuche mit `409 Conflict` ab (verhindert unkontrolliertes Überschreiben und Out-of-Order-Missbrauch). Andere Anwendungsteile lesen die Werte ausschließlich über den Service.

---

### 1. JPA-Entität (persistente Speicherung)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ApplicationSettings.java
package com.example.settings;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

@Entity
@Table(name = "application_settings")
public class ApplicationSettings {

    public static final long SINGLETON_ID = 1L;

    @Id
    private Long id = SINGLETON_ID;

    @Version
    private Long version;

    @Column(nullable = false, length = 64)
    private String defaultRole;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal maxRefundAmount;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "application_settings_feature_flags", joinColumns = @JoinColumn(name = "settings_id"))
    @MapKeyColumn(name = "flag_name", length = 64)
    @Column(name = "flag_enabled", nullable = false)
    private Map<String, Boolean> featureFlags = new HashMap<>();

    @Column(nullable = false, length = 254)
    private String supportEmail;

    @Column(nullable = false)
    private boolean maintenanceMode;

    @Column(nullable = false)
    private boolean initialized;

    protected ApplicationSettings() {
        // JPA
    }

    public static ApplicationSettings createDefaults() {
        ApplicationSettings settings = new ApplicationSettings();
        settings.id = SINGLETON_ID;
        settings.defaultRole = "USER";
        settings.maxRefundAmount = new BigDecimal("100.0000");
        settings.featureFlags = new HashMap<>();
        settings.featureFlags.put("newCheckout", Boolean.FALSE);
        settings.featureFlags.put("refundsEnabled", Boolean.TRUE);
        settings.supportEmail = "support@example.com";
        settings.maintenanceMode = false;
        settings.initialized = false;
        return settings;
    }

    public Long getId() {
        return id;
    }

    public Long getVersion() {
        return version;
    }

    public String getDefaultRole() {
        return defaultRole;
    }

    public void setDefaultRole(String defaultRole) {
        this.defaultRole = defaultRole;
    }

    public BigDecimal getMaxRefundAmount() {
        return maxRefundAmount;
    }

    public void setMaxRefundAmount(BigDecimal maxRefundAmount) {
        this.maxRefundAmount = maxRefundAmount;
    }

    public Map<String, Boolean> getFeatureFlags() {
        return featureFlags;
    }

    public void setFeatureFlags(Map<String, Boolean> featureFlags) {
        this.featureFlags = featureFlags != null ? new HashMap<>(featureFlags) : new HashMap<>();
    }

    public String getSupportEmail() {
        return supportEmail;
    }

    public void setSupportEmail(String supportEmail) {
        this.supportEmail = supportEmail;
    }

    public boolean isMaintenanceMode() {
        return maintenanceMode;
    }

    public void setMaintenanceMode(boolean maintenanceMode) {
        this.maintenanceMode = maintenanceMode;
    }

    public boolean isInitialized() {
        return initialized;
    }

    public void setInitialized(boolean initialized) {
        this.initialized = initialized;
    }
}
