### 3. Request-DTO mit Validierung und Sanitizing-Hinweisen

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// InitializeSettingsRequest.java
package com.example.settings;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.Map;

/**
 * Alle Felder sind optional: fehlende Werte behalten den Server-Default bzw. den
 * bereits gespeicherten Wert. Unbekannte JSON-Properties werden verworfen (Mass-Assignment-Schutz).
 */
@JsonIgnoreProperties(ignoreUnknown = true)
public class InitializeSettingsRequest {

    /**
     * Nur vordefinierte Rollen erlaubt (Whitelist, CWE-20).
     */
    @Size(max = 64)
    @Pattern(regexp = "^(USER|SUPPORT|ADMIN)$", message = "defaultRole must be one of USER, SUPPORT, ADMIN")
    private String defaultRole;

    @DecimalMin(value = "0.00", inclusive = true, message = "maxRefundAmount must be >= 0")
    @DecimalMax(value = "1000000.00", inclusive = true, message = "maxRefundAmount exceeds allowed maximum")
    private BigDecimal maxRefundAmount;

    /**
     * Flag-Namen werden im Service zusätzlich gegen eine Allowlist geprüft.
     */
    @Size(max = 32, message = "too many feature flags")
    private Map<@Size(min = 1, max = 64) @Pattern(regexp = "^[a-zA-Z][a-zA-Z0-9_]*$") String, Boolean> featureFlags;

    @Email(message = "supportEmail must be a valid e-mail address")
    @Size(max = 254)
    private String supportEmail;

    private Boolean maintenanceMode;

    public String getDefaultRole() {
        return defaultRole;
    }

    public void setDefaultRole(String defaultRole) {
        this.defaultRole = defaultRole;
    }

    public BigDecimal getMaxRefundAmount() {
        return maxRefundAmount;
    }

    public void setMaxRefundAmount(BigDecimal maxRefundAmount) {
        this.maxRefundAmount = maxRefundAmount;
    }

    public Map<String, Boolean> getFeatureFlags() {
        return featureFlags;
    }

    public void setFeatureFlags(Map<String, Boolean> featureFlags) {
        this.featureFlags = featureFlags;
    }

    public String getSupportEmail() {
        return supportEmail;
    }

    public void setSupportEmail(String supportEmail) {
        this.supportEmail = supportEmail;
    }

    public Boolean getMaintenanceMode() {
        return maintenanceMode;
    }

    public void setMaintenanceMode(Boolean maintenanceMode) {
        this.maintenanceMode = maintenanceMode;
    }
}
", "fileName": "Component_2", "vulnerbility": null}, {"type": "TEXT", "text": "

`@JsonIgnoreProperties(ignoreUnknown = true)` und gezielte Constraints verhindern Mass Assignment und Injection über unerwartete Felder. E-Mail, Rolle und Flag-Namen sind streng whitelisted bzw. formatgeprüft.

