        this.featureFlags = featureFlags == null
                ? Collections.emptyMap()
                : Collections.unmodifiableMap(featureFlags);
        this.supportEmail = supportEmail;
        this.maintenanceMode = maintenanceMode;
        this.initialized = initialized;
