package com.example.settings;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ApplicationSettingsService {

    private static final Logger log = LoggerFactory.getLogger(ApplicationSettingsService.class);

    /** Allowlist bekannter Feature-Flags – unbekannte Namen werden abgelehnt. */
    private static final Set<String> ALLOWED_FEATURE_FLAGS = Set.of(
            "newCheckout",
            "refundsEnabled",
            "betaUi");

    private final ApplicationSettingsRepository repository;

    public ApplicationSettingsService(ApplicationSettingsRepository repository) {
        this.repository = repository;
    }

    /**
     * Liefert die aktuellen Einstellungen (für andere Anwendungsteile).
     * Legt bei Bedarf die Default-Zeile an, markiert sie aber nicht als initialisiert.
     */
    @Transactional(readOnly = true)
    public ApplicationSettingsResponse getCurrentSettings() {
        ApplicationSettings settings = repository.findById(ApplicationSettings.SINGLETON_ID)
                .orElseGet(ApplicationSettings::createDefaults);
        return ApplicationSettingsResponse.from(settings);
    }

    /**
     * Einmalige Initialisierung: fehlende Request-Felder behalten Default/bestehenden Wert.
     */
    @Transactional
    public ApplicationSettingsResponse initialize(InitializeSettingsRequest request) {
        ApplicationSettings settings = repository.findById(ApplicationSettings.SINGLETON_ID)
                .orElseGet(ApplicationSettings::createDefaults);

        if (settings.isInitialized()) {
            log.warn("Rejected settings initialization: already initialized");
            throw new SettingsAlreadyInitializedException();
        }

        mergeIfPresent(settings, request);
        settings.setInitialized(true);

        ApplicationSettings saved = repository.save(settings);
        log.info("Application settings initialized successfully");
        return ApplicationSettingsResponse.from(saved);
    }

    private void mergeIfPresent(ApplicationSettings target, InitializeSettingsRequest request) {
        if (request.getDefaultRole() != null && !request.getDefaultRole().isBlank()) {
            target.setDefaultRole(request.getDefaultRole().trim().toUpperCase(Locale.ROOT));
        }

        if (request.getMaxRefundAmount() != null) {
            target.setMaxRefundAmount(request.getMaxRefundAmount());
        }

        if (request.getFeatureFlags() != null) {
            target.setFeatureFlags(validateAndSanitizeFeatureFlags(request.getFeatureFlags()));
        }

        if (request.getSupportEmail() != null && !request.getSupportEmail().isBlank()) {
            // Normalisierung: trim + lower-case local-part-unabhängig, Gesamtlänge bereits per @Email/@Size geprüft
            target.setSupportEmail(request.getSupportEmail().trim().toLowerCase(Locale.ROOT));
        }

        if (request.getMaintenanceMode() != null) {
            target.setMaintenanceMode(Boolean.TRUE.equals(request.getMaintenanceMode()));
        }
    }

    private Map<String, Boolean> validateAndSanitizeFeatureFlags(Map<String, Boolean> incoming) {
        if (incoming.isEmpty()) {
            return Collections.emptyMap();
        }
        Map<String, Boolean> sanitized = new HashMap<>();
        for (Map.Entry<String, Boolean> entry : incoming.entrySet()) {
            String name = entry.getKey();
            if (name == null || !ALLOWED_FEATURE_FLAGS.contains(name)) {
                throw new InvalidSettingsException("Unsupported feature flag: " + name);
            }
            if (entry.getValue() == null) {
                throw new InvalidSettingsException("Feature flag value must not be null: " + name);
            }
            sanitized.put(name, entry.getValue());
        }
        return sanitized;
    }
}
