### 7. REST-Controller (Method-Restriction, Content-Type, Access Control)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ApplicationSettingsController.java
package com.example.settings;

import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping(path = "/api/v1/settings", produces = MediaType.APPLICATION_JSON_VALUE)
public class ApplicationSettingsController {

    private final ApplicationSettingsService settingsService;

    public ApplicationSettingsController(ApplicationSettingsService settingsService) {
        this.settingsService = settingsService;
    }

    /**
     * Einmalige Initialisierung der Anwendungseinstellungen.
     * Nur ADMIN; ausschließlich application/json; nach Erfolg 201.
     */
    @PostMapping(path = "/initialize", consumes = MediaType.APPLICATION_JSON_VALUE)
    @PreAuthorize("hasRole('ADMIN')")
    public ResponseEntity<ApplicationSettingsResponse> initialize(
            @Valid @RequestBody InitializeSettingsRequest request) {
        ApplicationSettingsResponse body = settingsService.initialize(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(body);
    }

    /**
     * Lesen der aktuellen Einstellungen (ebenfalls geschützt).
     */
    @GetMapping
    @PreAuthorize("hasAnyRole('ADMIN', 'SUPPORT')")
    public ResponseEntity<ApplicationSettingsResponse> getSettings() {
        return ResponseEntity.ok(settingsService.getCurrentSettings());
    }
}
", "fileName": "Component_7", "vulnerbility": null}, {"type": "TEXT", "text": "

- Nur `POST` bzw. `GET` – andere Verben liefert Spring automatisch als `405 Method Not Allowed`.
- `consumes = APPLICATION_JSON` → unpassende Content-Types werden mit `415` abgelehnt.
- `@PreAuthorize` erzwingt lokale Access-Control-Entscheidung am Endpoint (REST-Security-Cheat-Sheet).
- Keine sensiblen Daten in der URL; Body nur über HTTPS betreiben.

