package com.example.cart.domain;

import java.util.Objects;

/**
 * Immutable cart line. Invariants are enforced in the constructor
 * (treated equivalently to construction during deserialization).
 */
public final class CartItem {

    private final long articleId;
    private final int quantity;

    public CartItem(long articleId, int quantity) {
        if (articleId <= 0L) {
            throw new IllegalArgumentException("articleId must be positive");
        }
        if (quantity <= 0 || quantity > 10_000) {
            throw new IllegalArgumentException("quantity out of allowed range");
        }
        this.articleId = articleId;
        this.quantity = quantity;
    }

    public long getArticleId() {
        return articleId;
    }

    public int getQuantity() {
        return quantity;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof CartItem)) {
            return false;
        }
        CartItem cartItem = (CartItem) o;
        return articleId == cartItem.articleId && quantity == cartItem.quantity;
    }

    @Override
    public int hashCode() {
        return Objects.hash(articleId, quantity);
    }
}
