"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Cart.java
package com.example.cart.domain;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

/**
 * Cart aggregate with implementation-defined invariants.
 * Mutable input lists are defensively copied; getters expose unmodifiable views
 * (SER06-J / SER07-J principles applied to JSON deserialization path).
 */
public final class Cart {

    private static final int MAX_ITEMS = 100;

    private final List<CartItem> items;

    public Cart(List<CartItem> items) {
        if (items == null || items.isEmpty()) {
            throw new IllegalArgumentException("cart must contain at least one item");
        }
        if (items.size() > MAX_ITEMS) {
            throw new IllegalArgumentException("cart exceeds maximum item count");
        }
        if (items.stream().anyMatch(Objects::isNull)) {
            throw new IllegalArgumentException("cart items must not be null");
        }

        // Defensive copy + duplicate articleId protection (invariant)
        List<CartItem> copy = new ArrayList<>(items.size());
        LinkedHashSet<Long> seen = new LinkedHashSet<>();
        for (CartItem item : items) {
            if (!seen.add(item.getArticleId())) {
                throw new IllegalArgumentException("duplicate articleId in cart");
            }
            copy.add(item);
        }
        this.items = Collections.unmodifiableList(copy);
    }

    public List<CartItem> getItems() {
        // Unmodifiable view; elements themselves are immutable
        return items;
    }

    public List<Long> getArticleIds() {
        return items.stream()
                .map(CartItem::getArticleId)
                .collect(Collectors.toList());
    }
}
