package com.example.cart.domain;

import java.math.BigDecimal;
import java.util.Objects;

/**
 * Trusted article entity loaded from the database. Prices always come from here,
 * never from the client payload.
 */
public final class Article {

    private final long id;
    private final String name;
    private final BigDecimal price;

    public Article(long id, String name, BigDecimal price) {
        if (id <= 0L) {
            throw new IllegalArgumentException("id must be positive");
        }
        if (name == null || name.isBlank() || name.length() > 200) {
            throw new IllegalArgumentException("invalid article name");
        }
        if (price == null || price.signum() < 0 || price.scale() > 4) {
            throw new IllegalArgumentException("invalid price");
        }
        this.id = id;
        this.name = name;
        this.price = price;
    }

    public long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getPrice() {
        return price;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Article)) {
            return false;
        }
        Article article = (Article) o;
        return id == article.id;
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }
}
