"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartDeserializer.java
package com.example.cart.security;

import com.example.cart.domain.Cart;
import com.example.cart.domain.CartItem;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * Whitelist-style custom deserializer: only known fields, strict types,
 * size limits and constructor invariants (SER07-J: deserialization == construction).
 * Does not support polymorphic types (mitigates CWE-502 gadget chains).
 */
public final class CartDeserializer extends JsonDeserializer<Cart> {

    private static final int MAX_ITEMS = 100;

    @Override
    public Cart deserialize(JsonParser parser, DeserializationContext ctxt) throws IOException {
        if (parser.currentToken() != JsonToken.START_OBJECT) {
            throw new CartDeserializationException("cart payload must be a JSON object");
        }

        List<CartItem> items = null;

        while (parser.nextToken() != JsonToken.END_OBJECT) {
            String fieldName = parser.currentName();
            parser.nextToken();

            if ("items".equals(fieldName)) {
                items = readItems(parser);
            } else {
                // Reject unexpected properties to reduce attack surface
                throw new CartDeserializationException("unknown field: " + fieldName);
            }
        }

        try {
            return new Cart(items);
        } catch (IllegalArgumentException ex) {
            throw new CartDeserializationException("cart invariant violation", ex);
        }
    }

    private List<CartItem> readItems(JsonParser parser) throws IOException {
        if (parser.currentToken() != JsonToken.START_ARRAY) {
            throw new CartDeserializationException("items must be a JSON array");
        }

        List<CartItem> items = new ArrayList<>();
        while (parser.nextToken() != JsonToken.END_ARRAY) {
            if (items.size() >= MAX_ITEMS) {
                throw new CartDeserializationException("too many cart items");
            }
            items.add(readItem(parser));
        }
        return items;
    }

    private CartItem readItem(JsonParser parser) throws IOException {
        if (parser.currentToken() != JsonToken.START_OBJECT) {
            throw new CartDeserializationException("cart item must be a JSON object");
        }

        Long articleId = null;
        Integer quantity = null;

        while (parser.nextToken() != JsonToken.END_OBJECT) {
            String fieldName = parser.currentName();
            parser.nextToken();

            switch (fieldName) {
                case "articleId" -> {
                    if (!parser.currentToken().isNumeric()) {
                        throw new CartDeserializationException("articleId must be numeric");
                    }
                    articleId = parser.getLongValue();
                }
                case "quantity" -> {
                    if (!parser.currentToken().isNumeric()) {
                        throw new CartDeserializationException("quantity must be numeric");
                    }
                    quantity = parser.getIntValue();
                }
                default -> throw new CartDeserializationException("unknown item field: " + fieldName);
            }
        }

        if (articleId == null || quantity == null) {
            throw new CartDeserializationException("articleId and quantity are required");
        }

        try {
            return new CartItem(articleId, quantity);
        } catch (IllegalArgumentException ex) {
            throw new CartDeserializationException("cart item invariant violation", ex);
        }
    }
}
