"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureObjectMapperFactory.java
package com.example.cart.security;

import com.example.cart.domain.Cart;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.SerializationFeature;

/**
 * Factory for a locked-down ObjectMapper:
 * - no default typing / polymorphic type ids
 * - fail on unexpected tokens where possible
 * - only Cart bound via custom deserializer
 */
public final class SecureObjectMapperFactory {

    private SecureObjectMapperFactory() {
    }

    public static ObjectMapper create() {
        ObjectMapper mapper = new ObjectMapper();

        // Harden against unexpected / oversized / polymorphic payloads
        mapper.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
        // unknown properties are rejected inside CartDeserializer explicitly
        mapper.enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
        mapper.disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
        mapper.deactivateDefaultTyping();

        SimpleModule module = new SimpleModule();
        module.addDeserializer(Cart.class, new CartDeserializer());
        mapper.registerModule(module);

        return mapper;
    }
}
