"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartPayloadDecoder.java
package com.example.cart.security;

import com.example.cart.domain.Cart;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * Base64 (untrusted) → UTF-8 JSON bytes → Cart via secure mapper only.
 * Size limits mitigate DoS; no Java ObjectInputStream (CWE-502).
 */
public final class CartPayloadDecoder {

    /** ~64 KiB decoded JSON upper bound */
    private static final int MAX_DECODED_BYTES = 64 * 1024;
    /** Base64 expands ~4/3; allow small overhead for padding/whitespace */
    private static final int MAX_ENCODED_CHARS = (MAX_DECODED_BYTES * 4) / 3 + 64;

    private final ObjectMapper objectMapper;

    public CartPayloadDecoder(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    public Cart decodeAndDeserialize(String encodedCart) {
        if (encodedCart == null || encodedCart.isBlank()) {
            throw new CartDeserializationException("encoded cart must not be empty");
        }
        if (encodedCart.length() > MAX_ENCODED_CHARS) {
            throw new CartDeserializationException("encoded cart exceeds size limit");
        }

        final byte[] jsonBytes;
        try {
            // MIME decoder tolerates line breaks; still reject after size check
            jsonBytes = Base64.getMimeDecoder().decode(encodedCart.trim());
        } catch (IllegalArgumentException ex) {
            throw new CartDeserializationException("invalid Base64 encoding", ex);
        }

        if (jsonBytes.length == 0 || jsonBytes.length > MAX_DECODED_BYTES) {
            throw new CartDeserializationException("decoded cart size invalid");
        }

        // Optional: ensure payload looks like UTF-8 JSON object
        String json = new String(jsonBytes, StandardCharsets.UTF_8).trim();
        if (!json.startsWith("{")) {
            throw new CartDeserializationException("decoded payload is not a JSON object");
        }

        try {
            return objectMapper.readValue(json, Cart.class);
        } catch (CartDeserializationException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new CartDeserializationException("unable to deserialize cart", ex);
        }
    }
}
