package com.example.cart.persistence;

import com.example.cart.domain.Article;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Demo repository. Replace with a JPA/JDBC implementation in production.
 * Never expose connection details through the API layer.
 */
@Repository
public class InMemoryArticleRepository implements ArticleRepository {

    private final Map<Long, Article> store = new LinkedHashMap<>();

    public InMemoryArticleRepository() {
        store.put(1L, new Article(1L, "Notebook", new BigDecimal("12.50")));
        store.put(2L, new Article(2L, "Pen", new BigDecimal("1.20")));
        store.put(3L, new Article(3L, "Backpack", new BigDecimal("39.90")));
    }

    @Override
    public Optional<Article> findById(long id) {
        return Optional.ofNullable(store.get(id));
    }

    @Override
    public List<Article> findAllById(Iterable<Long> ids) {
        List<Article> result = new ArrayList<>();
        for (Long id : ids) {
            Article article = store.get(id);
            if (article != null) {
                result.add(article);
            }
        }
        return result;
    }
}
