package com.example.cart.service;

import com.example.cart.domain.Article;
import com.example.cart.persistence.ArticleRepository;
import org.springframework.stereotype.Service;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

@Service
public class ArticleService {

    private final ArticleRepository articleRepository;

    public ArticleService(ArticleRepository articleRepository) {
        this.articleRepository = articleRepository;
    }

    /**
     * Returns articles keyed by id. Missing ids are reported to the caller
     * without leaking persistence details.
     */
    public Map<Long, Article> getArticlesById(List<Long> articleIds) {
        List<Article> found = articleRepository.findAllById(articleIds);
        Map<Long, Article> byId = new LinkedHashMap<>();
        for (Article article : found) {
            byId.put(article.getId(), article);
        }

        Set<Long> missing = articleIds.stream()
                .filter(id -> !byId.containsKey(id))
                .collect(Collectors.toSet());

        if (!missing.isEmpty()) {
            throw new ArticleNotFoundException("one or more articles not found");
        }
        return byId;
    }
}
