"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartService.java
package com.example.cart.service;

import com.example.cart.api.CartItemResponse;
import com.example.cart.api.CartResponse;
import com.example.cart.domain.Article;
import com.example.cart.domain.Cart;
import com.example.cart.domain.CartItem;
import com.example.cart.security.CartPayloadDecoder;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

@Service
public class CartService {

    private final CartPayloadDecoder cartPayloadDecoder;
    private final ArticleService articleService;

    public CartService(CartPayloadDecoder cartPayloadDecoder, ArticleService articleService) {
        this.cartPayloadDecoder = cartPayloadDecoder;
        this.articleService = articleService;
    }

    public CartResponse loadAndPriceCart(String encodedCart) {
        // 1) Secure decode + deserialize + invariant checks
        Cart cart = cartPayloadDecoder.decodeAndDeserialize(encodedCart);

        // 2) Load trusted catalog data (prices never taken from client)
        Map<Long, Article> articles = articleService.getArticlesById(cart.getArticleIds());

        // 3) Calculate totals from DB prices
        List<CartItemResponse> lines = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP);

        for (CartItem item : cart.getItems()) {
            Article article = articles.get(item.getArticleId());
            BigDecimal unit = article.getPrice().setScale(2, RoundingMode.HALF_UP);
            BigDecimal lineTotal = unit.multiply(BigDecimal.valueOf(item.getQuantity()))
                    .setScale(2, RoundingMode.HALF_UP);

            lines.add(new CartItemResponse(
                    article.getId(),
                    article.getName(),
                    item.getQuantity(),
                    unit,
                    lineTotal));
            total = total.add(lineTotal);
        }

        return new CartResponse(lines, total);
    }
}
