import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping(path = "/cart", produces = MediaType.APPLICATION_JSON_VALUE)
public class CartController {

    private final CartService cartService;

    public CartController(CartService cartService) {
        this.cartService = cartService;
    }

    /**
     * Accepts a raw Base64 string body (UTF-8). Content-Type: text/plain or application/json string.
     * Deserialization is delegated exclusively to the hardened pipeline.
     */
    @PostMapping(consumes = {MediaType.TEXT_PLAIN_VALUE, MediaType.APPLICATION_JSON_VALUE})
    public ResponseEntity<CartResponse> loadCart(@RequestBody String encodedCart) {
        CartResponse response = cartService.loadAndPriceCart(encodedCart);
        return ResponseEntity.ok(response);
    }
}
