package com.example.redirect.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;
import org.springframework.validation.annotation.Validated;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.util.ArrayList;
import java.util.List;

/**
 * Konfiguration der erlaubten Redirect-Ziele (Allow-List).
 * Werte werden aus application.yml / application.properties geladen.
 */
@Component
@ConfigurationProperties(prefix = "app.redirect")
@Validated
public class RedirectProperties {

    /**
     * Sichere Fallback-URL, wenn kein oder ein ungültiger Parameter geliefert wird.
     */
    @NotBlank
    private String defaultUrl = "/";

    /**
     * Explizite Allow-List von vollqualifizierten URLs oder Hosts,
     * zu denen umgeleitet werden darf. Niemals benutzergesteuerte Werte hier aufnehmen.
     */
    @NotEmpty
    private List<String> allowedTargets = new ArrayList<>();

    public String getDefaultUrl() {
        return defaultUrl;
    }

    public void setDefaultUrl(String defaultUrl) {
        this.defaultUrl = defaultUrl;
    }

    public List<String> getAllowedTargets() {
        return allowedTargets;
    }

    public void setAllowedTargets(List<String> allowedTargets) {
        this.allowedTargets = allowedTargets;
    }
}
