"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectService.java
package com.example.redirect.service;

import com.example.redirect.config.RedirectProperties;
import com.example.redirect.exception.InvalidRedirectException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.web.util.UriComponents;
import org.springframework.web.util.UriComponentsBuilder;

import java.net.URI;
import java.util.Locale;
import java.util.Optional;

/**
 * Zentrale Stelle für sichere Redirect-Auflösung.
 * - Allow-List-Prüfung (höchste Sicherheit gegen Open Redirect)
 * - Strikte URL-Validierung (Schema, Host)
 * - Audit-Logging jedes Redirect-Versuchs
 */
@Service
public class RedirectService {

    private static final Logger AUDIT_LOG = LoggerFactory.getLogger("REDIRECT_AUDIT");
    private static final Logger LOG = LoggerFactory.getLogger(RedirectService.class);

    private final RedirectProperties properties;

    public RedirectService(RedirectProperties properties) {
        this.properties = properties;
    }

    /**
     * Löst das Redirect-Ziel sicher auf.
     *
     * @param rawUrl vom Client gelieferter Wert (darf null/blank sein)
     * @param clientIp optionale Client-IP für das Audit-Log
     * @return validierte, absolute Ziel-URI
     */
    public URI resolveSafeRedirect(String rawUrl, String clientIp) {
        if (rawUrl == null || rawUrl.isBlank()) {
            URI fallback = toUri(properties.getDefaultUrl());
            audit("MISSING_PARAM", rawUrl, fallback.toString(), clientIp);
            return fallback;
        }

        String sanitized = rawUrl.trim();

        // 1. Grundlegende syntaktische & schema-Prüfung (nur https erlauben)
        URI candidate = parseAndValidateStructure(sanitized);

        // 2. Allow-List-Match (exakter Vergleich oder Host-Match)
        if (!isAllowed(candidate)) {
            audit("REJECTED_ALLOWLIST", sanitized, properties.getDefaultUrl(), clientIp);
            throw new InvalidRedirectException(
                    "Requested redirect target is not in the allow-list", sanitized);
        }

        audit("ALLOWED", sanitized, candidate.toString(), clientIp);
        return candidate;
    }

    private URI parseAndValidateStructure(String raw) {
        try {
            UriComponents components = UriComponentsBuilder
                    .fromUriString(raw)
                    .build(true);

            String scheme = Optional.ofNullable(components.getScheme())
                    .map(s -> s.toLowerCase(Locale.ROOT))
                    .orElse("");

            // Nur https (oder relative Pfade, die wir zu default machen) – verhindert javascript:, data: usw.
            if (!scheme.isEmpty() && !"https".equals(scheme)) {
                throw new InvalidRedirectException("Only https scheme is permitted", raw);
            }

            // Keine Userinfo (user:pass@host) erlauben – klassischer Open-Redirect-/SSRF-Vektor
            if (components.getUserInfo() != null) {
                throw new InvalidRedirectException("Userinfo in URL is not permitted", raw);
            }

            // Host muss vorhanden sein bei absoluten URLs
            if (!scheme.isEmpty() && (components.getHost() == null || components.getHost().isBlank())) {
                throw new InvalidRedirectException("Host is required for absolute URLs", raw);
            }

            return components.toUri();
        } catch (InvalidRedirectException ex) {
            throw ex;
        } catch (Exception ex) {
            LOG.debug("URL parsing failed for '{}': {}", sanitizeForLog(raw), ex.getMessage());
            throw new InvalidRedirectException("Malformed URL", raw);
        }
    }

    private boolean isAllowed(URI candidate) {
        String candidateStr = candidate.toString();
        String host = candidate.getHost() != null
                ? candidate.getHost().toLowerCase(Locale.ROOT)
                : "";

        for (String allowed : properties.getAllowedTargets()) {
            String normalizedAllowed = allowed.trim();
            if (normalizedAllowed.isEmpty()) {
                continue;
            }

            // Exakte URL-Übereinstimmung
            if (candidateStr.equalsIgnoreCase(normalizedAllowed)) {
                return true;
            }

            // Host-basierte Allow-List (z. B. "cdn.example.com")
            if (!host.isEmpty() && host.equals(normalizedAllowed.toLowerCase(Locale.ROOT))) {
                return true;
            }

            // Präfix-Match für erlaubte Basis-URLs (mit Trailing-Slash-Normalisierung)
            if (normalizedAllowed.endsWith("/") && candidateStr.regionMatches(true, 0, normalizedAllowed, 0, normalizedAllowed.length())) {
                return true;
            }
        }
        return false;
    }

    private URI toUri(String url) {
        return UriComponentsBuilder.fromUriString(url).build(true).toUri();
    }

    /**
     * Neutralizes CRLF and other control characters to prevent log injection (CWE-93).
     */
    private static String sanitizeForLog(String input) {
        if (input == null) {
            return "-";
        }
        StringBuilder sb = new StringBuilder(input.length());
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (c == '\r' || c == '\n' || c == '\t') {
                sb.append('_');
            } else if (c < 0x20 || c == 0x7F) {
                // strip other control characters
                sb.append('_');
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private void audit(String event, String requested, String resolved, String clientIp) {
        AUDIT_LOG.info(
                "event={} requested={} resolved={} clientIp={}",
                sanitizeForLog(event),
                sanitizeForLog(requested),
                sanitizeForLog(resolved),
                sanitizeForLog(clientIp));
    }
}
