"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.redirect.web;

import com.example.redirect.exception.InvalidRedirectException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.servlet.view.RedirectView;

/**
 * Mappt Sicherheitsverletzungen auf ein sicheres Fallback-Verhalten
 * (Redirect auf Default-Seite statt 500er oder Open Redirect).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger LOG = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(InvalidRedirectException.class)
    public RedirectView handleInvalidRedirect(InvalidRedirectException ex) {
        LOG.warn("Blocked redirect attempt to '{}': {}", ex.getRequestedTarget(), ex.getMessage());
        // Immer auf eine bekannte sichere Seite umleiten – nie die vom Angreifer gelieferte URL
        RedirectView redirectView = new RedirectView("/");
        redirectView.setStatusCode(HttpStatus.FOUND);
        redirectView.setPropagateQueryParams(false);
        return redirectView;
    }
}
