"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectController.java
package com.example.redirect.web;

import com.example.redirect.service.RedirectService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.view.RedirectView;

import java.net.URI;

/**
 * Sicherer Redirect-Endpunkt.
 *
 * GET /go?url=...
 *
 * Der Parameter wird niemals direkt an sendRedirect übergeben.
 * Stattdessen erfolgt eine vollständige serverseitige Validierung
 * gegen eine Allow-List (Schutz vor CWE-601 Open Redirect und CWE-918).
 */
@RestController
public class RedirectController {

    private final RedirectService redirectService;

    public RedirectController(RedirectService redirectService) {
        this.redirectService = redirectService;
    }

    @GetMapping("/go")
    public RedirectView go(
            @RequestParam(value = "url", required = false) String url,
            HttpServletRequest request) {

        String clientIp = extractClientIp(request);
        URI safeTarget = redirectService.resolveSafeRedirect(url, clientIp);

        RedirectView redirectView = new RedirectView(safeTarget.toString());
        // 302 Found ist für temporäre Redirects üblich; bei Bedarf 303/307 wählbar
        redirectView.setStatusCode(HttpStatus.FOUND);
        // Query-Parameter des ursprünglichen Requests nicht weiterreichen
        redirectView.setPropagateQueryParams(false);
        // Host-relative Redirects erzwingen keine offenen externen Sprünge
        redirectView.setHosts(); // leere Hosts → nur relative oder bereits validierte absolute URIs
        return redirectView;
    }

    /**
     * Einfache Client-IP-Ermittlung unter Berücksichtigung gängiger Proxy-Header.
     * In Produktionsumgebungen sollte die Vertrauenswürdigkeit der Header
     * (z. B. über ForwardedHeaderFilter) konfiguriert werden.
     */
    private String extractClientIp(HttpServletRequest request) {
        String forwarded = request.getHeader("X-Forwarded-For");
        if (forwarded != null && !forwarded.isBlank()) {
            // Ersten Eintrag nehmen (Client)
            return forwarded.split(",")[0].trim();
        }
        return request.getRemoteAddr();
    }
}
