package com.example.xmlprocessor.dto;

import jakarta.xml.bind.annotation.XmlAccessType;
import jakarta.xml.bind.annotation.XmlAccessorType;
import jakarta.xml.bind.annotation.XmlElement;
import jakarta.xml.bind.annotation.XmlElementWrapper;
import jakarta.xml.bind.annotation.XmlRootElement;

import java.util.ArrayList;
import java.util.List;

/**
 * JAXB-Mapping der eingehenden XML-Struktur.
 * Externe Verweise sind reine Nutzdaten (Elemente), keine XML-Entities.
 */
@XmlRootElement(name = "document")
@XmlAccessorType(XmlAccessType.FIELD)
public class DocumentDto {

    @XmlElement(name = "title", required = true)
    private String title;

    @XmlElement(name = "description")
    private String description;

    @XmlElementWrapper(name = "externalReferences")
    @XmlElement(name = "reference")
    private List<ExternalReferenceDto> externalReferences = new ArrayList<>();

    @XmlElementWrapper(name = "fields")
    @XmlElement(name = "field")
    private List<FieldDto> fields = new ArrayList<>();

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public List<ExternalReferenceDto> getExternalReferences() {
        return externalReferences;
    }

    public void setExternalReferences(List<ExternalReferenceDto> externalReferences) {
        this.externalReferences = externalReferences != null ? externalReferences : new ArrayList<>();
    }

    public List<FieldDto> getFields() {
        return fields;
    }

    public void setFields(List<FieldDto> fields) {
        this.fields = fields != null ? fields : new ArrayList<>();
    }
}
