package com.example.xmlprocessor.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;

/**
 * Konfigurierbare Whitelist und Fetch-Limits.
 * Keine Default-Freigabe interner Netze oder file:-URLs.
 */
@Component
@ConfigurationProperties(prefix = "app.xml-security")
public class XmlSecurityProperties {

    /**
     * Erlaubte absolute Basis-URLs (Prefix-Match nach Normalisierung), z. B. https://example.com/
     */
    private List<String> allowedUrlPrefixes = new ArrayList<>(List.of("https://example.com/"));

    private int connectTimeoutMs = 3_000;
    private int readTimeoutMs = 5_000;
    private int maxResponseBytes = 64 * 1024;
    private int maxRedirects = 0;

    public List<String> getAllowedUrlPrefixes() {
        return allowedUrlPrefixes;
    }

    public void setAllowedUrlPrefixes(List<String> allowedUrlPrefixes) {
        this.allowedUrlPrefixes = allowedUrlPrefixes != null ? allowedUrlPrefixes : new ArrayList<>();
    }

    public int getConnectTimeoutMs() {
        return connectTimeoutMs;
    }

    public void setConnectTimeoutMs(int connectTimeoutMs) {
        this.connectTimeoutMs = connectTimeoutMs;
    }

    public int getReadTimeoutMs() {
        return readTimeoutMs;
    }

    public void setReadTimeoutMs(int readTimeoutMs) {
        this.readTimeoutMs = readTimeoutMs;
    }

    public int getMaxResponseBytes() {
        return maxResponseBytes;
    }

    public void setMaxResponseBytes(int maxResponseBytes) {
        this.maxResponseBytes = maxResponseBytes;
    }

    public int getMaxRedirects() {
        return maxRedirects;
    }

    public void setMaxRedirects(int maxRedirects) {
        this.maxRedirects = maxRedirects;
    }
}
