"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlWhitelistValidator.java
package com.example.xmlprocessor.security;

import com.example.xmlprocessor.config.XmlSecurityProperties;
import com.example.xmlprocessor.exception.UnauthorizedUrlException;
import org.springframework.stereotype.Component;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Whitelist-Prüfung für anwendungsseitige URLs.
 * Verhindert unautorisierte externe Zugriffe und reduziert Open-Redirect-/SSRF-Missbrauch
 * (u. a. CWE-601, CWE-918), indem nur https und konfigurierte Prefixe erlaubt sind.
 */
@Component
public class UrlWhitelistValidator {

    private final XmlSecurityProperties properties;

    public UrlWhitelistValidator(XmlSecurityProperties properties) {
        this.properties = properties;
    }

    public List<String> extractAndValidate(List<String> candidateUrls) {
        List<String> validated = new ArrayList<>();
        if (candidateUrls == null) {
            return validated;
        }
        for (String raw : candidateUrls) {
            validated.add(validateAndNormalize(raw));
        }
        return validated;
    }

    public String validateAndNormalize(String rawUrl) {
        if (rawUrl == null || rawUrl.isBlank()) {
            throw new UnauthorizedUrlException("URL darf nicht leer sein");
        }

        final URI uri;
        try {
            uri = new URI(rawUrl.trim()).normalize();
        } catch (URISyntaxException ex) {
            throw new UnauthorizedUrlException("Ungültige URL-Syntax");
        }

        if (uri.getScheme() == null || uri.getHost() == null) {
            throw new UnauthorizedUrlException("URL muss Schema und Host enthalten");
        }

        String scheme = uri.getScheme().toLowerCase(Locale.ROOT);
        if (!"https".equals(scheme)) {
            throw new UnauthorizedUrlException("Nur HTTPS-URLs sind erlaubt");
        }

        if (uri.getUserInfo() != null) {
            throw new UnauthorizedUrlException("URLs mit Userinfo sind nicht erlaubt");
        }

        // Blockiert typische SSRF-Ziele auch bei Whitelist-Fehlkonfiguration
        String host = uri.getHost().toLowerCase(Locale.ROOT);
        if (isLiteralLocalOrPrivateHost(host)) {
            throw new UnauthorizedUrlException("Zugriff auf lokale/private Hosts ist verboten");
        }

        String normalized = uri.toString();
        boolean allowed = properties.getAllowedUrlPrefixes().stream()
                .filter(p -> p != null && !p.isBlank())
                .map(String::trim)
                .anyMatch(normalized::startsWith);

        if (!allowed) {
            throw new UnauthorizedUrlException("Unbefugter Zugriff auf externe Ressource: Host/URL nicht in Whitelist");
        }

        return normalized;
    }

    private boolean isLiteralLocalOrPrivateHost(String host) {
        if ("localhost".equals(host) || host.endsWith(".localhost") || "metadata.google.internal".equals(host)) {
            return true;
        }
        // Grobe Literal-IP-Filter (kein DNS-Lookup hier – Lookup erfolgt zusätzlich im Fetcher)
        if (host.matches("(?i)127\\..*")
                || host.matches("(?i)10\\..*")
                || host.matches("(?i)192\\.168\\..*")
                || host.matches("(?i)169\\.254\\..*")
                || host.matches("(?i)172\\.(1[6-9]|2[0-9]|3[0-1])\\..*")
                || "::1".equals(host)
                || "0.0.0.0".equals(host)) {
            return true;
        }
        return false;
    }
}
