"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SafeExternalContentFetcher.java
package com.example.xmlprocessor.security;

import com.example.xmlprocessor.config.XmlSecurityProperties;
import com.example.xmlprocessor.exception.UnauthorizedUrlException;
import com.example.xmlprocessor.exception.XmlProcessingException;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.io.InputStream;
import java.net.InetAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

/**
 * Lädt Whitelist-freigegebene HTTPS-Inhalte mit harten Limits.
 * Kein XML-Entity-Resolver – bewusst getrennt vom Parser (XXE-Prävention).
 */
@Component
public class SafeExternalContentFetcher {

    private final XmlSecurityProperties properties;
    private final UrlWhitelistValidator whitelistValidator;
    private final HttpClient httpClient;

    public SafeExternalContentFetcher(XmlSecurityProperties properties,
                                      UrlWhitelistValidator whitelistValidator) {
        this.properties = properties;
        this.whitelistValidator = whitelistValidator;
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(Duration.ofMillis(properties.getConnectTimeoutMs()))
                .followRedirects(properties.getMaxRedirects() > 0
                        ? HttpClient.Redirect.NORMAL
                        : HttpClient.Redirect.NEVER)
                .build();
    }

    public String fetch(String rawUrl) {
        String normalized = whitelistValidator.validateAndNormalize(rawUrl);
        URI uri = URI.create(normalized);

        assertResolvedAddressNotPrivate(uri);

        HttpRequest request = HttpRequest.newBuilder(uri)
                .timeout(Duration.ofMillis(properties.getReadTimeoutMs()))
                .header("Accept", "text/plain, application/json, application/xml, text/xml, */*")
                .GET()
                .build();

        try {
            HttpResponse<InputStream> response = httpClient.send(request, HttpResponse.BodyHandlers.ofInputStream());
            int status = response.statusCode();
            if (status < 200 || status >= 300) {
                throw new XmlProcessingException("Externe Ressource lieferte HTTP-Status " + status);
            }

            // Erneute Prüfung nach möglichen Redirects (falls aktiviert)
            response.uri();
            whitelistValidator.validateAndNormalize(response.uri().toString());
            assertResolvedAddressNotPrivate(response.uri());

            byte[] limited = readLimited(response.body(), properties.getMaxResponseBytes());
            return new String(limited, StandardCharsets.UTF_8);
        } catch (UnauthorizedUrlException ex) {
            throw ex;
        } catch (IOException | InterruptedException ex) {
            if (ex instanceof InterruptedException) {
                Thread.currentThread().interrupt();
            }
            throw new XmlProcessingException("Externe Ressource konnte nicht sicher geladen werden", ex);
        }
    }

    private void assertResolvedAddressNotPrivate(URI uri) {
        try {
            InetAddress[] addresses = InetAddress.getAllByName(uri.getHost());
            for (InetAddress address : addresses) {
                if (address.isAnyLocalAddress()
                        || address.isLoopbackAddress()
                        || address.isLinkLocalAddress()
                        || address.isSiteLocalAddress()
                        || address.isMulticastAddress()) {
                    throw new UnauthorizedUrlException("Aufgelöste Adresse zeigt auf nicht erlaubten Adressbereich");
                }
            }
        } catch (UnauthorizedUrlException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new XmlProcessingException("DNS-Auflösung der externen URL fehlgeschlagen", ex);
        }
    }

    private byte[] readLimited(InputStream in, int maxBytes) throws IOException {
        byte[] buffer = in.readNBytes(maxBytes + 1);
        if (buffer.length > maxBytes) {
            throw new XmlProcessingException("Externe Antwort überschreitet erlaubte Maximalgröße");
        }
        return buffer;
    }
}
