"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureJaxbXmlUnmarshaller.java
package com.example.xmlprocessor.xml;

import com.example.xmlprocessor.dto.DocumentDto;
import com.example.xmlprocessor.dto.ExternalReferenceDto;
import com.example.xmlprocessor.exception.XmlProcessingException;
import jakarta.xml.bind.JAXBContext;
import jakarta.xml.bind.JAXBException;
import jakarta.xml.bind.Unmarshaller;
import org.springframework.stereotype.Component;

import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamReader;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Sichere JAXB-Verarbeitung gemäß OWASP XXE Prevention Cheat Sheet.
 *
 * WICHTIG:
 * - DTDs deaktiviert (SUPPORT_DTD = false)
 * - External Entities deaktiviert (IS_SUPPORTING_EXTERNAL_ENTITIES = false)
 * - Unmarshaller erhält nur einen bereits gehärteten XMLStreamReader
 *
 * Dadurch werden CWE-611 (XXE), Entity-Expansion-DoS und parser-getriebene SSRF unterbunden.
 * „Auflösen externer Verweise“ erfolgt bewusst NICHT im XML-Parser, sondern später
 * über Whitelist + HTTP-Fetcher auf Element-URLs.
 */
@Component
public class SecureJaxbXmlUnmarshaller {

    private final JAXBContext jaxbContext;
    private final XMLInputFactory xmlInputFactory;

    public SecureJaxbXmlUnmarshaller() {
        try {
            this.jaxbContext = JAXBContext.newInstance(DocumentDto.class);
        } catch (JAXBException ex) {
            throw new IllegalStateException("JAXBContext konnte nicht initialisiert werden", ex);
        }

        XMLInputFactory factory = XMLInputFactory.newFactory();
        // Primäre XXE-Abwehr (OWASP): keine DTDs, keine externen Entities
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);
        // Zusätzliche Härtung, falls die Implementierung die Property kennt
        try {
            factory.setProperty("javax.xml.stream.isSupportingExternalEntities", false);
        } catch (IllegalArgumentException ignored) {
            // Provider-spezifisch – bereits über IS_SUPPORTING_EXTERNAL_ENTITIES abgedeckt
        }
        this.xmlInputFactory = factory;
    }

    public DocumentDto unmarshal(String xmlData) {
        if (xmlData == null || xmlData.isBlank()) {
            throw new XmlProcessingException("XML-Body darf nicht leer sein");
        }
        // Defense-in-Depth: offensichtliche DOCTYPE-Payloads früh ablehnen
        if (containsDoctype(xmlData)) {
            throw new XmlProcessingException("DOCTYPE ist nicht erlaubt (XXE-Schutz)");
        }

        try {
            XMLStreamReader reader = xmlInputFactory.createXMLStreamReader(new StringReader(xmlData));
            try {
                Unmarshaller unmarshaller = jaxbContext.createUnmarshaller();
                Object value = unmarshaller.unmarshal(reader);
                if (!(value instanceof DocumentDto document)) {
                    throw new XmlProcessingException("Unerwartetes XML-Wurzelelement");
                }
                return document;
            } finally {
                reader.close();
            }
        } catch (XMLStreamException | JAXBException ex) {
            throw new XmlProcessingException("XML konnte nicht sicher verarbeitet werden", ex);
        }
    }

    /**
     * Sammelt URL-Nutzdaten aus dem bereits sicher geparsten Dokument
     * (nicht aus DTD/Entity-Deklarationen).
     */
    public List<String> extractReferenceUrls(DocumentDto document) {
        List<String> urls = new ArrayList<>();
        if (document == null || document.getExternalReferences() == null) {
            return urls;
        }
        for (ExternalReferenceDto ref : document.getExternalReferences()) {
            if (ref != null && ref.getUrl() != null) {
                urls.add(ref.getUrl());
            }
        }
        return urls;
    }

    private boolean containsDoctype(String xmlData) {
        // Einfache, parser-unabhängige Vorprüfung; der StAX-Parser bleibt die maßgebliche Barriere
        String lower = xmlData.toLowerCase();
        return lower.contains("<!doctype") || lower.contains("<!entity");
    }
}
