package com.example.xmlprocessor.xml;

import com.example.xmlprocessor.dto.DocumentDto;
import com.example.xmlprocessor.dto.ExternalReferenceDto;
import com.example.xmlprocessor.dto.ProcessedDocumentResponse;
import com.example.xmlprocessor.dto.ResolvedReferenceResponse;
import com.example.xmlprocessor.exception.XmlProcessingException;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;

/**
 * Wandelt das Domänenobjekt mit Jackson in JSON um (kein unsicheres XML→JSON am Rohstring).
 */
@Component
public class XmlJsonConverter {

    private final ObjectMapper objectMapper;

    public XmlJsonConverter(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper.copy()
                .configure(SerializationFeature.INDENT_OUTPUT, true);
    }

    public ProcessedDocumentResponse toResponse(DocumentDto document) {
        ProcessedDocumentResponse response = new ProcessedDocumentResponse();
        response.setTitle(document.getTitle());
        response.setDescription(document.getDescription());
        response.setFields(document.getFields());

        List<ResolvedReferenceResponse> resolved = new ArrayList<>();
        if (document.getExternalReferences() != null) {
            for (ExternalReferenceDto ref : document.getExternalReferences()) {
                resolved.add(new ResolvedReferenceResponse(
                        ref.getUrl(),
                        ref.getType(),
                        ref.getResolvedContent()
                ));
            }
        }
        response.setResolvedReferences(resolved);
        return response;
    }

    public String toJson(ProcessedDocumentResponse response) {
        try {
            return objectMapper.writeValueAsString(response);
        } catch (JsonProcessingException ex) {
            throw new XmlProcessingException("JSON-Serialisierung fehlgeschlagen", ex);
        }
    }
}
