package com.example.xmlprocessor.service;

import com.example.xmlprocessor.dto.DocumentDto;
import com.example.xmlprocessor.dto.ExternalReferenceDto;
import com.example.xmlprocessor.dto.ProcessedDocumentResponse;
import com.example.xmlprocessor.security.SafeExternalContentFetcher;
import com.example.xmlprocessor.security.UrlWhitelistValidator;
import com.example.xmlprocessor.xml.SecureJaxbXmlUnmarshaller;
import com.example.xmlprocessor.xml.XmlJsonConverter;
import org.springframework.stereotype.Service;

import java.util.List;

/**
 * Orchestriert den sicheren Ablauf:
 * 1) XXE-sicheres Unmarshalling (kein Entity-Resolve im Parser)
 * 2) Whitelist der Element-URLs
 * 3) Kontrolliertes Nachladen
 * 4) JSON-Ausgabe der wichtigsten Felder
 */
@Service
public class XmlService {

    private final SecureJaxbXmlUnmarshaller unmarshaller;
    private final UrlWhitelistValidator whitelistValidator;
    private final SafeExternalContentFetcher contentFetcher;
    private final XmlJsonConverter jsonConverter;

    public XmlService(SecureJaxbXmlUnmarshaller unmarshaller,
                      UrlWhitelistValidator whitelistValidator,
                      SafeExternalContentFetcher contentFetcher,
                      XmlJsonConverter jsonConverter) {
        this.unmarshaller = unmarshaller;
        this.whitelistValidator = whitelistValidator;
        this.contentFetcher = contentFetcher;
        this.jsonConverter = jsonConverter;
    }

    public String parseXml(String xmlData) {
        DocumentDto document = unmarshaller.unmarshal(xmlData);

        List<String> urls = unmarshaller.extractReferenceUrls(document);
        // Wirft UnauthorizedUrlException, sobald eine URL nicht freigegeben ist
        whitelistValidator.extractAndValidate(urls);

        resolveExternalReferences(document);

        ProcessedDocumentResponse response = jsonConverter.toResponse(document);
        return jsonConverter.toJson(response);
    }

    /**
     * Löst nur whitelistegeprüfte, anwendungsseitige Verweise auf.
     * Das ist die sichere Alternative zu XML External Entities.
     */
    private void resolveExternalReferences(DocumentDto document) {
        if (document.getExternalReferences() == null) {
            return;
        }
        for (ExternalReferenceDto ref : document.getExternalReferences()) {
            if (ref == null || ref.getUrl() == null) {
                continue;
            }
            String content = contentFetcher.fetch(ref.getUrl());
            ref.setResolvedContent(content);
            // Normalisierte URL zurückschreiben (nach Whitelist)
            ref.setUrl(whitelistValidator.validateAndNormalize(ref.getUrl()));
        }
    }
}
