package com.example.xmlprocessor.web;

import com.example.xmlprocessor.exception.UnauthorizedUrlException;
import com.example.xmlprocessor.exception.XmlProcessingException;
import com.example.xmlprocessor.service.XmlService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/xml")
public class XmlController {

    private final XmlService xmlService;

    public XmlController(XmlService xmlService) {
        this.xmlService = xmlService;
    }

    /**
     * Nimmt XML im Body entgegen und liefert JSON.
     * Content-Type application/xml oder text/xml; Antwort application/json.
     */
    @PostMapping(
            consumes = {MediaType.APPLICATION_XML_VALUE, MediaType.TEXT_XML_VALUE, MediaType.ALL_VALUE},
            produces = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<String> processXml(@RequestBody String xmlData) {
        try {
            String jsonData = xmlService.parseXml(xmlData);
            return ResponseEntity.ok()
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(jsonData);
        } catch (UnauthorizedUrlException ex) {
            return ResponseEntity.badRequest()
                    .contentType(MediaType.TEXT_PLAIN)
                    .body(ex.getMessage());
        } catch (XmlProcessingException ex) {
            return ResponseEntity.badRequest()
                    .contentType(MediaType.TEXT_PLAIN)
                    .body(ex.getMessage());
        }
    }
}
