"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureXmlFactory.java
package com.example.customer.xml;

import com.example.customer.exception.XmlProcessingException;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import java.io.InputStream;

/**
 * Zentrale Fabrik für XXE-gehärtete JAXP-Komponenten.
 *
 * Umgesetzt gemäß OWASP XXE Prevention Cheat Sheet:
 * - DOCTYPE vollständig verboten
 * - External Entities / External DTDs deaktiviert
 * - FEATURE_SECURE_PROCESSING aktiv
 * - Kein XInclude, keine Entity-Expansion
 * - SchemaFactory ohne externes Schema-/DTD-Fetching
 */
public final class SecureXmlFactory {

    private SecureXmlFactory() {
        // Utility class
    }

    /**
     * Erzeugt eine gegen XXE gehärtete DocumentBuilderFactory.
     * Primäre Defense: disallow-doctype-decl.
     */
    public static DocumentBuilderFactory createSecureDocumentBuilderFactory() {
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

            // PRIMARY defense – verbietet DOCTYPE komplett (verhindert klassische XXE & Billion Laughs)
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Secure Processing (JDK 6+)
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Zusätzliche Absicherung für Parser, die DOCTYPE nicht vollständig verbieten können
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            dbf.setXIncludeAware(false);
            dbf.setExpandEntityReferences(false);
            dbf.setNamespaceAware(true);

            // JAXP 1.5+ : blockiert jeglichen externen Zugriff auf DTD/Schema
            dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            return dbf;
        } catch (ParserConfigurationException e) {
            throw new XmlProcessingException("Failed to configure secure DocumentBuilderFactory", e);
        }
    }

    /**
     * Lädt und kompiliert ein lokales XSD ohne externes Fetching.
     */
    public static Schema loadSchema(InputStream xsdStream) {
        if (xsdStream == null) {
            throw new XmlProcessingException("XSD schema resource not found");
        }
        try {
            SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
            schemaFactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            return schemaFactory.newSchema(new javax.xml.transform.stream.StreamSource(xsdStream));
        } catch (Exception e) {
            throw new XmlProcessingException("Failed to load or compile XSD schema", e);
        }
    }

    /**
     * Erzeugt einen DocumentBuilder, der das übergebene Schema zur Validierung nutzt.
     */
    public static DocumentBuilder createValidatingDocumentBuilder(Schema schema) {
        try {
            DocumentBuilderFactory dbf = createSecureDocumentBuilderFactory();
            dbf.setSchema(schema);
            DocumentBuilder builder = dbf.newDocumentBuilder();
            // Zusätzlicher No-Op EntityResolver als Defense-in-Depth
            builder.setEntityResolver((publicId, systemId) -> {
                throw new org.xml.sax.SAXException(
                        "External entity resolution is disabled. PublicId=" + publicId + ", SystemId=" + systemId);
            });
            return builder;
        } catch (ParserConfigurationException e) {
            throw new XmlProcessingException("Failed to create validating DocumentBuilder", e);
        }
    }
}
