"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerXmlService.java
package com.example.customer.service;

import com.example.customer.exception.CustomerNotFoundException;
import com.example.customer.exception.InvalidCustomerNameException;
import com.example.customer.exception.XmlProcessingException;
import com.example.customer.model.Customer;
import com.example.customer.xml.SecureXmlFactory;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

import javax.xml.validation.Schema;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Service zum sicheren Laden und Durchsuchen der Kunden-XML-Datei.
 *
 * Architektur:
 * 1. customerName wird streng validiert (Whitelist) → keine Injection in Suchlogik.
 * 2. XSD wird einmalig sicher geladen (kein externes Fetching).
 * 3. customers.xml wird mit DocumentBuilder + Schema-Validierung geparst.
 * 4. Filterung erfolgt nach dem Parse im Speicher (kein dynamisches XML-Query-Building
 *    mit Benutzereingabe → eliminiert XXE- und Injection-Oberfläche).
 */
@Service
public class CustomerXmlService {

    private static final Logger log = LoggerFactory.getLogger(CustomerXmlService.class);

    /**
     * Erlaubt nur Buchstaben (inkl. Umlaute), Leerzeichen, Bindestrich und Apostroph.
     * Länge 1–100. Verhindert Steuerzeichen und Markup-Injection.
     */
    private static final Pattern SAFE_NAME_PATTERN =
            Pattern.compile("^[\\p{L}][\\p{L}\\s'-]{0,99}$");

    private static final String XML_RESOURCE = "data/customers.xml";
    private static final String XSD_RESOURCE = "data/customers.xsd";

    private final Schema customerSchema;

    public CustomerXmlService() {
        this.customerSchema = loadSchemaOnce();
    }

    private Schema loadSchemaOnce() {
        try (InputStream xsdStream = new ClassPathResource(XSD_RESOURCE).getInputStream()) {
            return SecureXmlFactory.loadSchema(xsdStream);
        } catch (Exception e) {
            throw new XmlProcessingException("Cannot initialize customer XSD schema", e);
        }
    }

    /**
     * Sucht Kunden anhand des Namens (case-insensitive, Teilstring-Match auf dem validierten DOM).
     */
    public List<Customer> findByCustomerName(String customerName) {
        validateCustomerName(customerName);

        Document document = parseAndValidateCustomerXml();
        List<Customer> matches = filterByName(document, customerName);

        if (matches.isEmpty()) {
            throw new CustomerNotFoundException(customerName);
        }
        return matches;
    }

    private void validateCustomerName(String customerName) {
        if (customerName == null || customerName.isBlank()) {
            throw new InvalidCustomerNameException("customerName must not be blank");
        }
        String trimmed = customerName.trim();
        if (!SAFE_NAME_PATTERN.matcher(trimmed).matches()) {
            throw new InvalidCustomerNameException(
                    "customerName contains invalid characters or exceeds length limit");
        }
    }

    private Document parseAndValidateCustomerXml() {
        try (InputStream xmlStream = new ClassPathResource(XML_RESOURCE).getInputStream()) {
            var builder = SecureXmlFactory.createValidatingDocumentBuilder(customerSchema);
            // Jeder Parse-Fehler (inkl. Schema-Verletzung) wird als SAXException geworfen
            Document document = builder.parse(xmlStream);
            document.getDocumentElement().normalize();
            return document;
        } catch (XmlProcessingException e) {
            throw e;
        } catch (Exception e) {
            log.error("Secure XML parse/validation failed", e);
            throw new XmlProcessingException("Failed to parse or validate customer XML", e);
        }
    }

    private List<Customer> filterByName(Document document, String customerName) {
        String needle = customerName.trim().toLowerCase(Locale.ROOT);
        NodeList nodes = document.getElementsByTagName("customer");
        List<Customer> result = new ArrayList<>();

        for (int i = 0; i < nodes.getLength(); i++) {
            Element element = (Element) nodes.item(i);
            String name = textOf(element, "name");
            if (name != null && name.toLowerCase(Locale.ROOT).contains(needle)) {
                result.add(new Customer(
                        textOf(element, "id"),
                        name,
                        textOf(element, "email"),
                        textOf(element, "city")
                ));
            }
        }
        return result;
    }

    private static String textOf(Element parent, String tag) {
        NodeList list = parent.getElementsByTagName(tag);
        if (list.getLength() == 0 || list.item(0) == null) {
            return null;
        }
        return list.item(0).getTextContent();
    }
}
