package com.example.customer.web;

import com.example.customer.model.Customer;
import com.example.customer.service.CustomerXmlService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * REST-Endpunkt für die Kundensuche.
 *
 * GET /api/customers/search?customerName=Max
 *
 * Liefert die gefundenen Kunden als JSON. Die eigentliche XML-Verarbeitung
 * und XXE-Härtung liegen vollständig im Service-/Factory-Layer.
 */
@RestController
@RequestMapping(path = "/api/customers", produces = MediaType.APPLICATION_JSON_VALUE)
public class CustomerController {

    private final CustomerXmlService customerXmlService;

    public CustomerController(CustomerXmlService customerXmlService) {
        this.customerXmlService = customerXmlService;
    }

    @GetMapping("/search")
    public ResponseEntity<List<Customer>> searchByName(
            @RequestParam("customerName") String customerName) {

        List<Customer> customers = customerXmlService.findByCustomerName(customerName);
        return ResponseEntity.ok(customers);
    }
}
