"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ErrorResponse.java
package com.example.secureurlfetch.dto;

import java.time.Instant;

/**
 * Generisches Fehler-DTO.
 * Enthält bewusst keine internen Exception-Details, Stacktraces oder
 * benutzergesteuerte Eingaben – erfüllt CERT ERR01-J und CWE-209.
 */
public class ErrorResponse {

    private final String message;
    private final Instant timestamp;
    private final int status;

    public ErrorResponse(String message, int status) {
        this.message = message;
        this.status = status;
        this.timestamp = Instant.now();
    }

    public String getMessage() {
        return message;
    }

    public Instant getTimestamp() {
        return timestamp;
    }

    public int getStatus() {
        return status;
    }
}
