"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlValidator.java
package com.example.secureurlfetch.validation;

import com.example.secureurlfetch.exception.InvalidUrlException;
import org.springframework.stereotype.Component;

import java.net.InetAddress;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.UnknownHostException;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Strenge URL-Validierung gegen SSRF, Open-Redirect und Injection-Angriffe.
 * Verwendet ausschließlich die JDK-Klassen URI/InetAddress (keine veralteten Parser).
 *
 * Gelöste Schwachstellen:
 * - CWE-79 (XSS/Injection über manipulierte URLs)
 * - SSRF auf interne Netze und Cloud-Metadata-Endpunkte
 */
@Component
public class UrlValidator {

    private static final Set<String> ALLOWED_SCHEMES = Set.of("http", "https");
    private static final int MAX_URL_LENGTH = 2048;

    // Einfache, aber strenge Host-Syntax (kein Userinfo, keine IP-Literale in eckigen Klammern ohne Prüfung)
    private static final Pattern SAFE_HOST_PATTERN =
            Pattern.compile("^[a-zA-Z0-9]([a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])?(\\.[a-zA-Z0-9]([a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])?)*$");

    /**
     * Validiert und parst die URL. Wirft InvalidUrlException bei jedem Verstoß.
     */
    public URI validateAndParse(String rawUrl) {
        if (rawUrl == null || rawUrl.isBlank()) {
            throw new InvalidUrlException("URL must not be empty");
        }
        if (rawUrl.length() > MAX_URL_LENGTH) {
            throw new InvalidUrlException("URL exceeds maximum allowed length");
        }

        final URI uri;
        try {
            uri = new URI(rawUrl.trim());
        } catch (URISyntaxException ex) {
            throw new InvalidUrlException("Malformed URL", ex);
        }

        // Schema strikt whitelisten
        String scheme = uri.getScheme();
        if (scheme == null || !ALLOWED_SCHEMES.contains(scheme.toLowerCase(Locale.ROOT))) {
            throw new InvalidUrlException("Only http and https schemes are allowed");
        }

        // Userinfo (user:pass@) verbieten – klassischer SSRF-/Credential-Leak-Vektor
        if (uri.getUserInfo() != null) {
            throw new InvalidUrlException("Userinfo component is not allowed");
        }

        String host = uri.getHost();
        if (host == null || host.isBlank()) {
            throw new InvalidUrlException("Host must be present");
        }

        // Host-Syntax prüfen (verhindert einige Parser-Differenzen)
        if (!SAFE_HOST_PATTERN.matcher(host).matches() && !isLiteralIp(host)) {
            throw new InvalidUrlException("Host contains illegal characters");
        }

        // Port-Range absichern
        int port = uri.getPort();
        if (port != -1 && (port < 1 || port > 65535)) {
            throw new InvalidUrlException("Port out of valid range");
        }

        // DNS-Auflösung und Private-/Reserved-IP-Blockade (Kern der SSRF-Mitigation)
        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress addr : addresses) {
                if (isForbiddenAddress(addr)) {
                    throw new InvalidUrlException("Target address is not allowed");
                }
            }
        } catch (UnknownHostException ex) {
            throw new InvalidUrlException("Host cannot be resolved", ex);
        }

        return uri;
    }

    private boolean isLiteralIp(String host) {
        // Sehr grobe Erkennung; die eigentliche Prüfung erfolgt über InetAddress
        return host.chars().allMatch(c -> (c >= '0' && c <= '9') || c == '.' || c == ':');
    }

    /**
     * Blockiert Loopback, Link-Local, Site-Local, Any-Local, Multicast
     * sowie bekannte Cloud-Metadata-Adressen (z. B. 169.254.169.254).
     */
    private boolean isForbiddenAddress(InetAddress addr) {
        return addr.isAnyLocalAddress()
                || addr.isLoopbackAddress()
                || addr.isLinkLocalAddress()
                || addr.isSiteLocalAddress()
                || addr.isMulticastAddress()
                || isCloudMetadataAddress(addr);
    }

    private boolean isCloudMetadataAddress(InetAddress addr) {
        // AWS/GCP/Azure Metadata-Service
        byte[] bytes = addr.getAddress();
        if (bytes.length == 4) { // IPv4
            // 169.254.169.254
            return (bytes[0] == (byte) 169 && bytes[1] == (byte) 254
                    && bytes[2] == (byte) 169 && bytes[3] == (byte) 254);
        }
        return false;
    }
}
", "fileName": "Component_4", "vulnerbility": null}, {"type": "TEXT", "text": "

Der Validator ist die zentrale Verteidigungslinie gegen SSRF und bösartige URL-Payloads. Durch die explizite DNS-Auflösung und die Prüfung jeder zurückgegebenen Adresse werden DNS-Rebinding- und IPv6-Tricks deutlich erschwert.

