"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlValidator.java
package com.example.secureurlfetch.validation;

import com.example.secureurlfetch.exception.UrlFetchException;
import org.springframework.stereotype.Component;

import java.net.IDN;
import java.net.InetAddress;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.UnknownHostException;
import java.util.Locale;
import java.util.Set;

/**
 * Strikte URL-Validierung gegen SSRF (CWE-918):
 * - Nur https-Schema
 * - Host-Allowlist
 * - Blockieren von privaten, Loopback-, Link-Local- und Metadata-IPs
 * - Keine User-Info in der URL
 * - DNS-Auflösung wird gegen interne Netze geprüft
 */
@Component
public class UrlValidator {

    /**
     * Explizite Allowlist erlaubter Hosts.
     * Nur diese Domains dürfen angefragt werden.
     */
    private static final Set<String> ALLOWED_HOSTS = Set.of(
            "api.example.com",
            "cdn.example.com",
            "files.example.org"
    );

    public URI validateAndParse(String rawUrl) {
        if (rawUrl == null || rawUrl.isBlank()) {
            throw new UrlFetchException("URL must not be empty");
        }

        // Steuerzeichen / CRLF-Injection in Headern verhindern
        if (rawUrl.chars().anyMatch(c -> c < 0x20 || c == 0x7F)) {
            throw new UrlFetchException("URL contains illegal characters");
        }

        final URI uri;
        try {
            uri = new URI(rawUrl.trim());
        } catch (URISyntaxException ex) {
            throw new UrlFetchException("Malformed URL");
        }

        // Schema: ausschließlich HTTPS
        String scheme = uri.getScheme();
        if (scheme == null || !scheme.equalsIgnoreCase("https")) {
            throw new UrlFetchException("Only HTTPS URLs are allowed");
        }

        // Keine Credentials in der URL
        if (uri.getUserInfo() != null) {
            throw new UrlFetchException("User info in URL is not allowed");
        }

        // Host muss vorhanden sein
        String host = uri.getHost();
        if (host == null || host.isBlank()) {
            throw new UrlFetchException("URL host is required");
        }

        // Normalisieren (IDN → ASCII) und Lower-Case
        String normalizedHost;
        try {
            normalizedHost = IDN.toASCII(host).toLowerCase(Locale.ROOT);
        } catch (IllegalArgumentException ex) {
            throw new UrlFetchException("Invalid host name");
        }

        // Allowlist-Prüfung
        if (!ALLOWED_HOSTS.contains(normalizedHost)) {
            throw new UrlFetchException("Host is not in the allowlist");
        }

        // Port: nur Default-HTTPS oder explizit 443
        int port = uri.getPort();
        if (port != -1 && port != 443) {
            throw new UrlFetchException("Only port 443 is allowed");
        }

        // Keine Fragmente (vermeidet mehrdeutige Parser-Unterschiede)
        if (uri.getFragment() != null) {
            throw new UrlFetchException("URL fragments are not allowed");
        }

        // DNS auflösen und alle resultierenden Adressen auf interne/reservierte Ranges prüfen
        try {
            InetAddress[] addresses = InetAddress.getAllByName(normalizedHost);
            if (addresses == null || addresses.length == 0) {
                throw new UrlFetchException("Host could not be resolved");
            }
            for (InetAddress address : addresses) {
                if (isBlockedAddress(address)) {
                    throw new UrlFetchException("Resolved address is not allowed");
                }
            }
        } catch (UnknownHostException ex) {
            throw new UrlFetchException("Host could not be resolved");
        }

        // Kanonische URI ohne User-Info zurückgeben (nur erlaubte Komponenten)
        try {
            return new URI(
                    "https",
                    null,
                    normalizedHost,
                    -1,
                    uri.getPath() == null || uri.getPath().isEmpty() ? "/" : uri.getPath(),
                    uri.getQuery(),
                    null
            );
        } catch (URISyntaxException ex) {
            throw new UrlFetchException("Failed to normalize URL");
        }
    }

    /**
     * Blockiert Loopback, Link-Local, Site-Local/Private, Any-Local,
     * Multicast und bekannte Cloud-Metadata-Endpunkte.
     */
    private boolean isBlockedAddress(InetAddress address) {
        if (address.isAnyLocalAddress()
                || address.isLoopbackAddress()
                || address.isLinkLocalAddress()
                || address.isSiteLocalAddress()
                || address.isMulticastAddress()) {
            return true;
        }

        // Zusätzliche Prüfung der Roh-Bytes (IPv4 und IPv4-mapped IPv6)
        byte[] bytes = address.getAddress();
        if (bytes.length == 4) {
            return isBlockedIpv4(bytes);
        }
        if (bytes.length == 16) {
            // IPv4-mapped IPv6: ::ffff:a.b.c.d
            boolean isIpv4Mapped = true;
            for (int i = 0; i < 10; i++) {
                if (bytes[i] != 0) {
                    isIpv4Mapped = false;
                    break;
                }
            }
            if (isIpv4Mapped && (bytes[10] & 0xFF) == 0xFF && (bytes[11] & 0xFF) == 0xFF) {
                return isBlockedIpv4(new byte[]{bytes[12], bytes[13], bytes[14], bytes[15]});
            }
            // Unique Local Addresses (fc00::/7)
            if ((bytes[0] & 0xFE) == 0xFC) {
                return true;
            }
        }
        return false;
    }

    private boolean isBlockedIpv4(byte[] b) {
        int a0 = b[0] & 0xFF;
        int a1 = b[1] & 0xFF;
        int a2 = b[2] & 0xFF;

        // 0.0.0.0/8
        if (a0 == 0) {
            return true;
        }
        // 10.0.0.0/8
        if (a0 == 10) {
            return true;
        }
        // 127.0.0.0/8
        if (a0 == 127) {
            return true;
        }
        // 169.254.0.0/16 (Link-Local / Cloud-Metadata 169.254.169.254)
        if (a0 == 169 && a1 == 254) {
            return true;
        }
        // 172.16.0.0/12
        if (a0 == 172 && a1 >= 16 && a1 <= 31) {
            return true;
        }
        // 192.168.0.0/16
        if (a0 == 192 && a1 == 168) {
            return true;
        }
        // 100.64.0.0/10 (Carrier-Grade NAT)
        if (a0 == 100 && a1 >= 64 && a1 <= 127) {
            return true;
        }
        // 192.0.0.0/24, 192.0.2.0/24 (TEST-NET-1), 198.18.0.0/15, 198.51.100.0/24, 203.0.113.0/24
