        }
        if (a0 == 198 && (a1 == 18 || a1 == 19 || a1 == 51)) {
            return true;
        }
        if (a0 == 203 && a1 == 0 && a2 == 113) {
            return true;
        }
        // Broadcast
        if (a0 == 255 && a1 == 255 && a2 == 255 && (b[3] & 0xFF) == 255) {
            return true;
        }
        return false;
    }
}
