"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.secureurlfetch.exception;

import com.example.secureurlfetch.dto.ErrorResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.AuthenticationException;
import org.springframework.web.bind.MissingServletRequestParameterException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Zentraler Exception-Handler gemäß CERT ERR01-J.
 * - Gibt niemals Exception-Messages, Stacktraces oder interne Pfade zurück.
 * - Loggt die echte Ursache nur serverseitig.
 * - Liefert einheitliche, generische Fehlermeldungen + passende HTTP-Statuscodes.
 *
 * Adressiert: CWE-209, CWE-600, CWE-209 (Information Exposure through Error Message)
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(InvalidUrlException.class)
    public ResponseEntity<ErrorResponse> handleInvalidUrl(InvalidUrlException ex) {
        // Echte Ursache nur loggen, Client erhält generische Meldung
        log.warn("Invalid URL rejected: {}", ex.getMessage());
        return build(HttpStatus.BAD_REQUEST, "The provided URL is invalid or not allowed");
    }

    @ExceptionHandler(UrlFetchException.class)
    public ResponseEntity<ErrorResponse> handleFetch(UrlFetchException ex) {
        log.error("URL fetch failed: {}", ex.getMessage());
        return build(HttpStatus.BAD_GATEWAY, "Unable to retrieve the requested resource");
    }

    @ExceptionHandler(MissingServletRequestParameterException.class)
    public ResponseEntity<ErrorResponse> handleMissingParam(MissingServletRequestParameterException ex) {
        return build(HttpStatus.BAD_REQUEST, "Required parameter is missing");
    }

    @ExceptionHandler({AuthenticationException.class})
    public ResponseEntity<ErrorResponse> handleAuth(AuthenticationException ex) {
        return build(HttpStatus.UNAUTHORIZED, "Authentication required");
    }

    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<ErrorResponse> handleAccessDenied(AccessDeniedException ex) {
        return build(HttpStatus.FORBIDDEN, "Access denied");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGeneric(Exception ex) {
        // Fängt alles Unerwartete ab – keine Details nach außen
        log.error("Unexpected error", ex);
        return build(HttpStatus.INTERNAL_SERVER_ERROR, "An internal error occurred");
    }

    private ResponseEntity<ErrorResponse> build(HttpStatus status, String clientMessage) {
        ErrorResponse body = new ErrorResponse(clientMessage, status.value());
        return ResponseEntity.status(status).body(body);
    }
}
