package com.example.secureurlfetch.security;

import com.example.secureurlfetch.dto.ErrorResponse;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;

/**
 * Einfaches In-Memory Rate-Limiting + temporäres IP-Blocking.
 * Schützt vor Missbrauch und DoS (CWE-400).
 *
 * Für Produktionsumgebungen sollte ein verteilter Store (Redis + Bucket4j)
 * oder ein API-Gateway verwendet werden.
 */
@Component
public class RateLimitingFilter extends OncePerRequestFilter {

    private static final Logger log = LoggerFactory.getLogger(RateLimitingFilter.class);

    private static final int MAX_REQUESTS_PER_MINUTE = 20;
    private static final int BLOCK_THRESHOLD = 5;
    private static final long BLOCK_DURATION_SECONDS = 300L;

    private static final String UNKNOWN_IP = "unknown";

    /** Erlaubt nur syntaktisch gültige IPv4- und IPv6-Adressen. */
    private static final Pattern SAFE_IP_PATTERN = Pattern.compile(
            "^(?:(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d)(?:\\.(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d)){3}"
                    + "|(?:[0-9a-fA-F]{1,4}:){1,7}[0-9a-fA-F]{0,4}"
                    + "|::(?:[0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{0,4}"
                    + "|(?:[0-9a-fA-F]{1,4}:){1,6}:)$"
    );

    /**
     * Allowlist für Log-Ausgaben: ausschließlich Zeichen, die in IPv4/IPv6 vorkommen.
     * CRLF, Leerzeichen und Steuerzeichen sind damit strukturell ausgeschlossen (CWE-93).
     */
    private static final Pattern LOG_SAFE_CHARS = Pattern.compile("^[0-9a-fA-F.:]+$");

    private final Map<String, Window> requestWindows = new ConcurrentHashMap<>();
    private final Map<String, Instant> blockedUntil = new ConcurrentHashMap<>();
    private final Map<String, AtomicInteger> violations = new ConcurrentHashMap<>();
    private final ObjectMapper objectMapper = new ObjectMapper();

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain)
            throws ServletException, IOException {

        final String safeClientIp = resolveClientIp(request);

        Instant blocked = blockedUntil.get(safeClientIp);
        if (blocked != null && Instant.now().isBefore(blocked)) {
            writeError(response, HttpStatus.TOO_MANY_REQUESTS,
                    "Your IP has been temporarily blocked due to excessive requests");
            return;
        } else if (blocked != null) {
            blockedUntil.remove(safeClientIp);
            violations.remove(safeClientIp);
        }

        Window window = requestWindows.computeIfAbsent(safeClientIp, k -> new Window());
        synchronized (window) {
            long now = System.currentTimeMillis();
            if (now - window.windowStart > 60_000L) {
                window.windowStart = now;
                window.count = 0;
            }
            window.count++;

            if (window.count > MAX_REQUESTS_PER_MINUTE) {
                int viol = violations.computeIfAbsent(safeClientIp, k -> new AtomicInteger()).incrementAndGet();
                // CWE-93: ausschließlich allowlist-gefilterte, CRLF-freie Werte loggen
                final String logSafeIp = toLogSafeToken(safeClientIp);
                log.warn("Rate limit exceeded for IP {} (violation #{})", logSafeIp, viol);
                if (viol >= BLOCK_THRESHOLD) {
                    blockedUntil.put(safeClientIp, Instant.now().plusSeconds(BLOCK_DURATION_SECONDS));
                    log.warn("IP {} blocked for {} seconds", logSafeIp, BLOCK_DURATION_SECONDS);
                }
                writeError(response, HttpStatus.TOO_MANY_REQUESTS,
                        "Rate limit exceeded. Please try again later");
                return;
            }
        }

        filterChain.doFilter(request, response);
    }

    /**
     * Ermittelt die Client-IP ausschließlich über Whitelist-Validierung.
     * Rückgabe ist garantiert CRLF-frei und enthält keine Steuerzeichen (CWE-93):
     * entweder eine gegen SAFE_IP_PATTERN geprüfte Adresse oder {@link #UNKNOWN_IP}.
     */
    private String resolveClientIp(HttpServletRequest request) {
        String forwarded = request.getHeader("X-Forwarded-For");
        if (forwarded != null && !forwarded.isBlank()) {
            String candidate = extractFirstHop(forwarded);
            String validated = validateIpOrUnknown(candidate);
            if (!UNKNOWN_IP.equals(validated)) {
                return validated;
            }
        }
        return validateIpOrUnknown(request.getRemoteAddr());
    }

    /**
     * Nimmt nur den ersten Hop und entfernt alle Steuer-/Whitespace-Zeichen frühzeitig.
     */
    private static String extractFirstHop(String forwarded) {
        int comma = forwarded.indexOf(',');
        String first = (comma >= 0 ? forwarded.substring(0, comma) : forwarded).trim();
        return stripControlAndWhitespace(first);
    }

    /**
     * Whitelist: nur syntaktisch gültige IPv4/IPv6-Adressen; sonst "unknown".
     * Damit gelangen keine CRLF-/Steuerzeichen in Logs oder Map-Keys (CWE-93).
     */
    private static String validateIpOrUnknown(String value) {
        if (value == null || value.isEmpty()) {
            return UNKNOWN_IP;
        }
        String cleaned = stripControlAndWhitespace(value);
        if (SAFE_IP_PATTERN.matcher(cleaned).matches()) {
            return cleaned;
        }
        return UNKNOWN_IP;
    }

    /**
     * Entfernt CRLF, Tabs und übrige C0/C1-Steuerzeichen vollständig.
     */
    private static String stripControlAndWhitespace(String value) {
        if (value == null || value.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder(value.length());
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '\r' || c == '\n' || c == '\t') {
                continue;
            }
            if (c <= 0x1F || c == 0x7F || (c >= 0x80 && c <= 0x9F)) {
                continue;
            }
            if (Character.isWhitespace(c)) {
                continue;
            }
            sb.append(c);
        }
        return sb.toString();
    }

    /**
     * Finale Allowlist-Neutralisierung für Log-Ausgaben (CWE-93 / Log Injection).
     * <ul>
     *   <li>Nur Zeichen aus [0-9a-fA-F.:] werden übernommen (kein CR/LF/Space möglich).</li>
     *   <li>Anschließend erneute IP-Whitelist-Prüfung bzw. Fallback auf {@link #UNKNOWN_IP}.</li>
     * </ul>
     * Es werden niemals Rohdaten aus HTTP-Headern in den Logger geschrieben.
     */
    private static String toLogSafeToken(String value) {
        if (value == null || value.isEmpty()) {
            return UNKNOWN_IP;
        }
        if (UNKNOWN_IP.equals(value)) {
            return UNKNOWN_IP;
        }

        StringBuilder sb = new StringBuilder(value.length());
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if ((c >= '0' && c <= '9')
                    || (c >= 'a' && c <= 'f')
                    || (c >= 'A' && c <= 'F')
                    || c == '.'
                    || c == ':') {
                sb.append(c);
            }
        }

        String token = sb.toString();
        if (token.isEmpty() || !LOG_SAFE_CHARS.matcher(token).matches()) {
            return UNKNOWN_IP;
        }
        if (!SAFE_IP_PATTERN.matcher(token).matches()) {
            return UNKNOWN_IP;
        }
        return token;
    }

    private void writeError(HttpServletResponse response, HttpStatus status, String message)
            throws IOException {
        response.setStatus(status.value());
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        ErrorResponse body = new ErrorResponse(message, status.value());
        objectMapper.writeValue(response.getOutputStream(), body);
    }

    private static final class Window {
        long windowStart = System.currentTimeMillis();
        int count = 0;
    }
}
